/* بيانات باب hayawan: تُحمَّل عند أول فتح للقسم */
window.HAYAWAN = {"ch":[{"id":"rusul","t":"كائنات في قصص الأنبياء","d":"حيوانات وطيور جاءت في قصص الرسل والصالحين: ما كان لها من دور في القصة وما ذكره المفسرون من وجه العبرة."},{"id":"ayat","t":"كائنات جعلها الله آية وجنداً","d":"ما أرسله الله من الحيوان والطير آيةً أو عقوبةً أو جنداً: الفيل وطير الأبابيل، والجراد والقمل والضفادع، ودابة الأرض."},{"id":"amthal","t":"أمثال ضُربت بالحيوان","d":"ما ضربه القرآن من الأمثال بالكلب والحمار والبعوضة والعنكبوت والذباب والفراش والقردة والجمل، وما فسّر به العلماء وجه الشبه."},{"id":"nima","t":"نعمة التسخير والمنافع","d":"ما امتنّ الله به على الناس من الحيوان: النحل والأنعام والإبل والخيل والطير المسخّر في الجو."},{"id":"umam","t":"الحيوان أمم وعبادة ورزق","d":"آيات تجعل الدواب والطير أمماً مثلنا، تسبّح وتسجد وتُرزق، وآية «شرّ الدواب»."}],"tp":[{"id":"hudhud","ch":"rusul","t":"الهدهد: الرسول الأمين إلى سليمان","e":"خبر الهدهد الذي غاب عن سليمان وجاءه بنبأ سبأ.","ay":[[27,20,28]],"q":[{"bk":"saadi","s":27,"ay":22,"x":"{فمكث غير بعيدٍ}: ثم جاء، وهذا يدلُّ على هيبة جنوده منه وشدَّة ائتمارهم لأمره، حتى إن هذا الهدهد الذي خَلَّفَه العذرُ الواضح لم يقدِرْ على التخلُّف زمناً كثيراً، {فقال} لسليمانَ: {أحطتُ بما لم تُحِطۡ به}؛ أي: عندي من العلم علمٌ ما أحطتَ به على علمك الواسع وعلوِّ درجتك فيه، {وجئتُك من سبأ}: القبيلة المعروفة في اليمن {بنبأ يقين}؛ أي: خبر متيقن. {23} ثم فسَّر هذا النبأ فقال: {إني وجدتُ امرأةً تملِكُهم}؛ أي: تملك قبيلة سبأ، وهي امرأة، {وأوتِيَتۡ من كلِّ شيءٍ}: يؤتاه الملوك من الأموال والسلاح والجنود والحصون وقلاع ونحو ذلك، {ولها عرشٌ عظيمٌ}؛ أي: كرسي ملكها الذي تجلس عليه عرشٌ هائلٌ، وعِظَمُ العروش تدُلُّ على عظمة المملكة وقوة السلطان وكثرة رجال الشورى.","w":"السعدي","en":"Al-Sa'di: the hoopoe could not stay away long; he came back and said he had knowledge Solomon had not encompassed, news he was sure of from Sheba: that a woman ruled them, was given of everything, and had a great throne, the greatness of whose throne shows the greatness of her kingdom."},{"bk":"saadi","s":27,"ay":24,"x":"{وجدتُها وقَوۡمَها يسجُدون للشمس من دونِ الله}؛ أي: هم مشرِكون يعبُدون الشمس، {وزيَّن لهم الشيطانُ أعمالَهم}: فرأوا ما هم عليه هو الحقَّ، {فهم لا يهتدونَ}: لأنَّ الذي يرى أنَّ الذي عليه حقٌّ لا مطمعَ في هدايته حتى تتغيَّر عقيدتُه. {25} ثم قال: {ألاَّ}؛ أي: هلاَّ {يسجدوا لله الذي يُخۡرِجُ الخَبۡءَ في السمواتِ والأرض}؛ أي: يعلم الخفي الخبيء في أقطار السماوات وأنحاء الأرض من صغارِ المخلوقات وبذور النباتات وخفايا الصدور، ويخرج خَبْءَ الأرض والسماء بإنزال المطر وإنبات النبات، ويخرِجُ خَبْءَ الأرض عند النفخ في الصور وإخراج الأموات من الأرض ليجازِيَهم بأعمالهم، {ويعلم ما تُخفون وما تُعۡلِنون}.","w":"السعدي","en":"Al-Sa'di: the hoopoe found her and her people prostrating to the sun instead of Allah, Satan having made their deeds look fair; and one who sees his way as right is not hoped to be guided until his belief changes. He then asked why they do not prostrate to Allah who brings out what is hidden in the heavens and the earth."},{"bk":"saadi","s":27,"ay":20,"x":"ولم يصنع شيئاً مَنْ قال: إنَّه تفقَّد الطير لينظرَ أين الهدهد منه ليدلَّه على بعدِ الماء وقربِهِ؛ كما زعموا عن الهدهد أنَّه يبصِرُ الماء تحت الأرض الكثيفة؛ فإنَّ هذا القول لا يدلُّ عليه دليلٌ، بل الدليلُ العقليُّ واللفظيُّ دالٌّ على بطلانِهِ: أما العقليُّ؛ فإنَّه قد عُرِفَ بالعادة والتجارب والمشاهدات أنَّ هذه الحيوانات كلَّها ليس منها شيءٌ يبصر هذا البصرَ الخارقَ للعادة وينظر الماءَ تحت الأرض الكثيفة، ولو كان كذلك؛ لَذَكَرَهُ الله؛ لأنَّه من أكبر الآيات. وأما الدليلُ اللفظيُّ؛ فلو أريد هذا المعنى؛ لقال: وطلب الهدهدَ لينظر له الماء، فلمَّا فقده؛ قال ما قال، أو: فَفَتَّش عن الهدهد، أو: بحث عنه.","w":"السعدي","en":"Al-Sa'di: nothing is achieved by saying Solomon sought the hoopoe to find water underground; there is no evidence for it, and reason and the wording of the verse both show it false, since observation shows these creatures do not have such extraordinary sight."},{"bk":"saadi","s":27,"ay":21,"x":"فحينئذٍ تغيَّظَ عليه وتوعَّده فقال: {لأعذِّبَنَّه عذاباً شديداً}: دون القتل {أو لأذۡبَحَنَّه أو ليأتِيَنِّي بسلطانٍ مبينٍ}؛ أي: حجة واضحة على تخلُّفه. وهذا من كمال ورعِهِ وإنصافِهِ؛ أنَّه لم يقسم على مجرَّد عقوبته بالعذاب أو القتل؛ لأنَّ ذلك لا يكون إلاَّ من ذنبٍ، وغيبته قد تحتمل أنها لعذرٍ واضح؛ فلذلك استثناه لورعه وفطنته.","w":"السعدي","en":"Al-Sa'di: Solomon was angry and swore to punish him severely, short of killing, or to slaughter him, unless he brought a clear proof; this was out of his scrupulousness and fairness, since the absence might have a plain excuse, so he made an exception."}]},{"id":"naml","ch":"rusul","t":"النملة: التحذير والنصح للجماعة","e":"قول النملة لقومها حين مرّ سليمان وجنوده.","ay":[[27,18,19]],"q":[{"bk":"saadi","s":27,"ay":18,"x":"فسار بهذه الجنودِ الضخمةِ في بعض أسفاره، {حتى إذا أتَوۡا على وادي النمل قالت نملةٌ}: منبهةٌ لرفقتها وبني جنسها: {يا أيُّها النملُ ادخُلوا مساكِنَكم لا يَحۡطِمَنَّكُم سليمانُ وجنودُه وهم لا يشعرونَ}: فنصحت هذه النملة وأسمعتِ النمل: إما بنفسِها، ويكون الله قد أعطى النملَ أسماعاً خارقةً للعادة؛ لأنَّ التنبيه للنمل الذي قد ملأ الوادي بصوت نملةٍ واحدة من أعجب العجائب. وإما بأنَّها أخْبَرَتْ مَنْ حولَها من النمل ثم سرى الخبرُ من بعضهنَّ لبعضٍ حتى بَلَغَ الجميع وأمَرَتْهُنَّ بالحذر والطريق في ذلك، وهو دخول مساكنهنَّ، وعرفت حالة سليمان وجنوده وعظمةَ سلطانِهِ، واعتذرتْ عنهم أنَّهم إنْ حَطَموكم؛ فليس عن قصدٍ منهم ولا شعورٍ.","w":"السعدي","en":"Al-Sa'di: Solomon marched with his great armies and reached the valley of the ants; one ant warned her kind to enter their dwellings lest Solomon and his troops crush them unawares. She advised and made the ants hear, either herself or by news passed from one to another, and she excused Solomon's army: they would not do it on purpose."},{"bk":"ibnkathir","s":27,"ay":18,"x":"أَيْ: خَافَتْ عَلَى النَّمْلِ أَنْ تَحْطِمَهَا الْخُيُولُ بِحَوَافِرِهَا، فَأَمَرَتْهُمْ بِالدُّخُولِ إِلَى مَسَاكِنِهَا فَفَهِمَ ذَلِكَ سُلَيْمَانُ، عَلَيْهِ السَّلَامُ، مِنْهَا .","w":"ابن كثير","en":"Ibn Kathir: she feared the horses would crush the ants with their hooves, so she ordered them into their dwellings, and Solomon understood this from her."},{"bk":"saadi","s":27,"ay":19,"x":"فسمع سليمانُ عليه الصلاة والسلامُ قولَها وفَهِمَهُ، {فتبسَّمَ ضاحكاً من قولِها}: إعجاباً منه بفصاحتها ونُصحها وحسن تعبيرها، وهذا حال الأنبياء عليهم الصلاة والسلام؛ الأدبُ الكاملُ، والتعجُّب في موضعه، وأنْ لا يبلغَ بهم الضَّحِك إلاَّ إلى التبسُّم؛ كما كان الرسول - صلى الله عليه وسلم - جُلُّ ضَحِكِهِ التبسُّمُ؛ فإنَّ القهقهةَ تدلُّ على خفة العقل وسوء الأدب، وعدم التبسُّم والعجب مما يُتَعَجَّب منه يدلُّ على شراسةِ الخلق والجبروت، والرسل منزَّهون عن ذلك. وقال شاكراً لله الذي أوصله إلى هذه الحال:{ربِّ أوۡزِعۡني}؛ أي: ألهمني ووفقني {أنۡ أشكُرَ نعمتَكَ التي أنعمتَ عليَّ وعلى والديَّ}: فإنَّ النعمةَ على الوالدين نعمةٌ على الولد، فسأل ربَّه التوفيق للقيام بشكر نعمتِهِ الدينيَّة والدنيويَّة عليه وعلى والديه، {وأنۡ أعملَ صالحاً ترضاه}؛ أي: ووفِّقْني أن أعمل صالحاً ترضاه …","w":"السعدي","en":"Al-Sa'di: Solomon heard and understood her and smiled, laughing, in admiration of her eloquence and counsel. This is the way of the prophets: perfect manners, wonder where it belongs, and laughter reaching no further than a smile, whereas loud laughter shows light-mindedness. He then prayed to be inspired to thank Allah for His favour on him and his parents."}]},{"id":"dhib","ch":"rusul","t":"الذئب: عذر الإخوة وخوف الأب","e":"خوف يعقوب على يوسف من الذئب، وعذر الإخوة الكاذب.","ay":[[12,13,17]],"q":[{"bk":"saadi","s":12,"ay":13,"x":"فأجابهم بقوله: {إنِّي ليحزُنُني أن تذهبوا به}؛ أي:مجرَّد ذهابكم به يحزنني ويشقُّ عليَّ؛ لأنني لا أقدر على فراقه، ولو مدة يسيرة؛ فهذا مانع من إرساله.{و} مانعٌ ثانٍ، وهو أني {أخاف أن يأكله الذئب وأنتُم عنه غافلون}؛ أي: في حال غفلتكم عنه؛ لأنه صغيرٌ لا يمتنع من الذئب. {14}{قالوا لئنۡ أكلَهُ الذئبُ ونحن عصبةٌ}؛ أي: جماعة حريصون على حفظه؛ {إنَّا إذاً لخاسرون}؛ أي: لا خير فينا ولا نفع يُرجى منَّا إن أكله الذئب وغلبنا عليه.","w":"السعدي","en":"Al-Sa'di: Jacob answered that merely their taking Joseph would grieve him because he could not bear separation, and that he feared the wolf would eat him while they were heedless of him, for he was young and could not defend himself; they replied that if the wolf ate him while they were a strong group, they would be losers."},{"bk":"saadi","s":12,"ay":17,"x":"فقالوا متعذرين بعذرٍ كاذب: {يا أبانا إنَّا ذهبنا نَسۡتَبِقُ}: إما على الأقدام أو بالرمي والنضال، {وتركۡنا يوسف عند متاعنا}: توفيراً له وراحة، {فأكله الذئبُ}: في حال غيبتنا عنه واستباقنا.","w":"السعدي","en":"Al-Sa'di: the brothers said, as a false excuse, that they went racing, either on foot or at archery, and left Joseph with their things, and the wolf ate him while they were away."},{"bk":"qurtubi","s":12,"ay":17,"x":"(فَأَكَلَهُ الذِّئْبُ) وذلك أنهم ما سَمِعُوا أَبَاهُمْ يَقُولُ: \"وَأَخافُ أَنْ يَأْكُلَهُ الذِّئْبُ\" أَخَذُوا ذَلِكَ مِنْ فِيهِ فَتَحَرَّمُوا بِهِ، لِأَنَّهُ كَانَ أَظْهَرَ الْمَخَاوِفِ عَلَيْهِ.","w":"القرطبي","en":"Al-Qurtubi: they took the word from their father's own mouth, since he had said he feared the wolf would eat him, because it was the most obvious danger for him."}]},{"id":"ghurab","ch":"rusul","t":"الغراب: معلّم الدفن الأول","e":"الغراب الذي بعثه الله ليري ابن آدم كيف يوارى سوأة أخيه.","ay":[[5,27,31]],"q":[{"bk":"saadi","s":5,"ay":31,"x":"فلما قَتَلَ أخاه؛ لم يدرِ كيف يصنعُ به؛ لأنه أول ميت مات من بني آدم، {فبَعَثَ الله غُراباً يبحثُ في الأرض}؛ أي: يثيرُها ليدفنَ غُراباً آخر ميتاً. {لِيُرِيَهُ}: بذلك {كيف يُواري سوأة أخيهِ}؛ أي: بَدَنَه؛ لأنَّ بدن الميت يكون عورةً، {فأصبح من النادمين}: وهكذا عاقبة المعاصي الندامة والخسارة.","w":"السعدي","en":"Al-Sa'di: when he killed his brother he did not know what to do with the body, the first dead person among the children of Adam; Allah sent a raven digging in the earth to bury another dead raven, to show him how to cover his brother's body, and he became one of the regretful. Such is the end of sins: regret and loss."},{"bk":"ibnkathir","s":5,"ay":31,"x":"وَقَوْلُهُ تَعَالَى: ﴿فَبَعَثَ اللَّهُ غُرَابًا يَبْحَثُ فِي الأرْضِ لِيُرِيَهُ كَيْفَ يُوَارِي سَوْأَةَ أَخِيهِ قَالَ يَا وَيْلَتَى أَعَجَزْتُ أَنْ أَكُونَ مِثْلَ هَذَا الْغُرَابِ فَأُوَارِيَ سَوْأَةَ أَخِي فَأَصْبَحَ مِنَ النَّادِمِينَ﴾ قَالَ السُّدِّيُّ بِإِسْنَادِهِ الْمُتَقَدِّمِ إِلَى الصَّحَابَةِ: لَمَّا مَاتَ الْغُلَامُ تَرَكَهُ بالعَرَاء، وَلَا يَعْلَمُ كَيْفَ يُدْفَنُ، فَبَعَثَ اللَّهُ غُرَابَيْنِ أَخَوَيْنِ، فَاقْتَتَلَا فَقَتَلَ أَحَدُهُمَا صَاحِبَهُ، فَحَفَرَ لَهُ ثُمَّ حَثَى عَلَيْهِ.","w":"ابن كثير","en":"Ibn Kathir: Allah sent a raven to show him how to cover his brother's body; he said, 'Alas, am I unable to be like this raven?' and became regretful. Al-Suddi reported that the boy was left in the open, he did not know how to bury, so Allah sent two brother ravens that fought until one killed the other, then dug and covered him with earth."},{"bk":"qurtubi","s":5,"ay":31,"x":"وَقِيلَ: إِنَّ الْغُرَابَ بَحَثَ الْأَرْضَ عَلَى طُعْمِهِ لِيُخْفِيَهُ إِلَى وَقْتِ الْحَاجَةِ إِلَيْهِ، لِأَنَّهُ مِنْ عَادَةِ الْغُرَابِ فِعْلُ ذلك، فتنبه قابيل ذلك عَلَى مُوَارَاةِ أَخِيهِ.","w":"القرطبي","en":"Al-Qurtubi: it is also said that the raven was digging for its own food to hide it until it was needed, which is the raven's habit, and that this made Cain realise how to cover his brother."}]},{"id":"yunus","ch":"rusul","t":"الحوت: يونس في بطنه ونجاته","e":"التقام الحوت يونس ونجاته بالتسبيح.","ay":[[37,139,148],[21,87,88],[68,48,50]],"q":[{"bk":"saadi","s":37,"ay":142,"x":"{فالۡتَقَمَهُ الحوتُ وهو}: وقت التقامِهِ {مُليمٌ}؛ أي: فاعلٌ ما يُلام عليه، وهو مغاضبتُهُ لربِّه.","w":"السعدي","en":"Al-Sa'di: the whale swallowed him while he was blameworthy, which was his leaving in anger from his Lord."},{"bk":"saadi","s":37,"ay":143,"x":"{فلولا أنَّه كان من المسبِّحينَ}؛ أي: في وقتِه السابقِ بكثرةِ عبادته لربِّه وتسبيحِهِ وتحميدِهِ وفي بطن الحوت حيث قال: {لا إله إلا أنت سبحانَكَ إنِّي كُنۡتُ من الظالمين}؛ {لَلَبِثَ في بطنِهِ إلى يوم يُبۡعَثونَ}؛ أي: لكانتْ مقبرتَهَ، ولكن بسبب تسبيحِهِ وعبادتِهِ لله؛ نجَّاه الله تعالى، وكذلك ينجي الله المؤمنين عند وقوعهم في الشدائد. {145}{فَنبَذۡناه بالعراءِ}: بأنْ قَذَفَهُ الحوت من بطنِهِ بالعراء، وهي الأرض الخالية العاريةُ من كلِّ أحدٍ، بل ربَّما كانت عارية من الأشجارِ والظِّلال.","w":"السعدي","en":"Al-Sa'di: had he not been among those who glorify Allah, before and in the whale's belly, saying 'There is no god but You, glory to You, I was among the wrongdoers', he would have stayed there until the Day of Resurrection, so it would have been his grave; because of his glorification Allah saved him, and likewise He saves believers in hardship. Then he was cast onto the bare shore."},{"bk":"ibnkathir","s":37,"ay":143,"x":"وَفِي حَدِيثٍ عَنِ ابْنِ عَبَّاسٍ: \" تَعَرف إِلَى اللَّهِ فِي الرَّخَاءِ يَعْرِفْكَ فِي الشِّدَّةِ\" وَقَالَ ابْنُ عَبَّاسٍ، وَسَعِيدُ بْنُ جُبَيْر، وَالضَّحَّاكُ، وَعَطَاءُ بْنُ السَّائِبِ، وَالسُّدِّيُّ، وَالْحَسَنُ، وَقَتَادَةُ: ﴿فَلَوْلا أَنَّهُ كَانَ مِنَ الْمُسَبِّحِينَ﴾ يَعْنِي: الْمُصَلِّينَ. وَصَرَّحَ بَعْضُهُمْ بِأَنَّهُ كَانَ مِنَ الْمُصَلِّينَ قَبْلَ ذَلِكَ.","w":"ابن كثير","en":"Ibn Kathir: in a hadith from Ibn Abbas, 'Know Allah in ease, He will know you in hardship.' Ibn Abbas and others said 'those who glorify' means those who pray, and some stated that he had been among those who prayed before that."}]},{"id":"hutmusa","ch":"rusul","t":"الحوت الذي نسيه موسى وفتاه","e":"الحوت الذي نسيه موسى وفتاه عند مجمع البحرين.","ay":[[18,60,64]],"q":[{"bk":"saadi","s":18,"ay":61,"x":"وهذا عزمٌ منه جازم، فلذلك أمضاه، {فلما بلغا}؛ أي: هو وفتاه {مَجۡمَعَ بينهما نسيا حوتَهما}: وكان معهما حوتٌ يتزوَّدان منه ويأكلان، وقد وُعِدَ أنَّه متى فقد الحوت؛ فثمَّ ذلك العبد الذي قصدته. {فاتَّخذ}: ذلك الحوت {سبيلَه}؛ أي: طريقه {في البحر سَرَباً}.","w":"السعدي","en":"Al-Sa'di: that was a firm resolve, so he carried it out; when they reached the meeting of the two seas they forgot their fish, which they carried as provision; he had been told that when he lost the fish, the servant he sought would be there. The fish took its way into the sea."},{"bk":"ibnkathir","s":18,"ay":61,"x":"وَقَوْلُهُ: ﴿فَلَمَّا بَلَغَا مَجْمَعَ بَيْنِهِمَا نَسِيَا حُوتَهُمَا﴾ ، وَذَلِكَ أَنَّهُ كَانَ قَدْ أُمِرَ بِحَمْلِ حُوتٍ مَمْلُوحٍ مَعَهُ، وَقِيلَ لَهُ: مَتَى فقدتَ الْحُوتَ فَهُوَ ثَمّة. فَسَارَا حَتَّى بَلَغَا مَجْمَعَ الْبَحْرَيْنِ؛ وَهُنَاكَ عَيْنٌ يُقَالُ لَهَا: \"عَيْنُ الْحَيَاةِ\"، فَنَامَا هُنَالِكَ، وَأَصَابَ الْحُوتُ مِنْ رَشَاشِ ذَلِكَ الْمَاءِ فَاضْطَرَبَ ، وَكَانَ فِي مِكْتَلٍ مَعَ يُوشَعَ [عَلَيْهِ السَّلَامُ] ، وطَفَر مِنَ المَكْتل إِلَى الْبَحْرِ، فَاسْتَيْقَظَ يُوشع، عَلَيْهِ السَّلَامُ، وَسَقَطَ الْحُوتُ فِي الْبَحْرِ وَجَعَلَ يَسِيرُ فِيهِ، وَالْمَاءُ لَهُ مِثْلُ الطَّاقِ لَا يَلْتَئِمُ بَعْدَهُ؛ وَلِهَذَا قَالَ: ﴿فَاتَّخَذَ سَبِيلَهُ فِي الْبَحْرِ سَرَبًا﴾ أَيْ: مِثْلَ السَرَب في الأرض.","w":"ابن كثير","en":"Ibn Kathir: he had been ordered to carry a salted fish and told that wherever he lost it, that is the place; they reached the meeting of the two seas where there is a spring, the fish felt its spray and moved, and slipped from the basket into the sea, going its way like a tunnel in the earth."}]},{"id":"naqa","ch":"rusul","t":"ناقة صالح: آية مبصرة وفتنة","e":"ناقة صالح آيةً لثمود وعقرهم لها.","ay":[[7,73,79],[11,64,65],[54,27,31],[91,11,15]],"q":[{"bk":"saadi","s":7,"ay":73,"x":"أي: خارق من خوارق العادات التي لا تكون إلا آية سماويَّة لا يقدر الناس عليها، ثم فسَّرها بقوله:{هذه ناقةُ الله لكم آية}؛ أي: هذه ناقةٌ شريفةٌ فاضلةٌ لإضافتها إلى الله تعالى إضافة تشريف، لكم فيها آية عظيمة، وقد ذكر وجه الآية في قوله:{لها شِرۡبٌ ولكم شِرۡبُ يوم معلوم}، وكان عندهم بئر كبيرةٌ، وهي المعروفة ببئر الناقة، يتناوبونها هم والناقة، للناقة يوم تشربها ويشربون اللبن من ضرعها، ولهم يوم يردونها وتصدر الناقة عنهم. وقال لهم نبيُّهم صالح عليه السلام:{فذَروها تأكلۡ في أرض الله}: فلا عليكم من مؤونتها شيء، {ولا تَمَسُّوها بسوءٍ}؛ أي: بعقر أو غيره، {فيأخذَكُم عذابٌ أليم}.","w":"السعدي","en":"Al-Sa'di: the sign was an extraordinary thing only heaven can give: 'this is the she-camel of Allah, a sign for you'; honoured by being ascribed to Allah. They shared the well, she drinking one day and they drinking her milk, they another day; Salih told them to let her graze in Allah's land and not touch her with harm, or a painful punishment would seize them."},{"bk":"qurtubi","s":7,"ay":73,"x":"وَأُضِيفَتِ النَّاقَةُ إِلَى اللَّهِ عَزَّ وَجَلَّ عَلَى جِهَةِ إِضَافَةِ الْخَلْقِ إِلَى الْخَالِقِ.","w":"القرطبي","en":"Al-Qurtubi: the she-camel was ascribed to Allah as the creature is ascribed to its Creator."},{"bk":"saadi","s":7,"ay":77,"x":"{فعقروا الناقة}: التي توعَّدهم إن مسوها بسوء أن يصيبَهم عذابٌ أليم.","w":"السعدي","en":"Al-Sa'di: 'they hamstrung the she-camel', the one against whom they had been warned that if they touched her with harm a painful punishment would reach them."}]},{"id":"kabsh","ch":"rusul","t":"الكبش: فداء إسماعيل","e":"الذبح العظيم الذي فُدي به إسماعيل.","ay":[[37,100,111]],"q":[{"bk":"saadi","s":37,"ay":107,"x":"{وفديناه بِذبۡحٍ عظيم}؛ أي: صار بَدَلَه ذبحٌ من الغنم عظيمٌ ذبحه إبراهيم، فكان عظيماً: من جهة أنَّه كان فداء لإسماعيلَ، ومن جهة أنَّه من جملة العبادات الجليلة، ومن جهة أنه كان قرباناً وسنةً إلى يوم القيامةِ. {108 ـ 109}{وتركنا عليه في الآخرين.","w":"السعدي","en":"Al-Sa'di: 'We ransomed him with a great sacrifice': an animal of the flock took his place, which Abraham slaughtered; it was great because it ransomed Ishmael, because it was a noble act of worship, and because it became an offering and a tradition until the Day of Resurrection."},{"bk":"ibnkathir","s":37,"ay":107,"x":"وَقَالَ مُحَمَّدُ بْنُ إِسْحَاقَ، عَنِ الْحَسَنِ بْنِ دِينَارٍ، عَنْ قَتَادَةَ، عَنْ جَعْفَرِ بْنِ إِيَاسٍ، عَنِ ابْنِ عَبَّاسٍ فِي قَوْلِهِ: ﴿وَفَدَيْنَاهُ بِذِبْحٍ عَظِيمٍ﴾ قَالَ: خَرَجَ عَلَيْهِ كَبْشٌ مِنَ الْجَنَّةِ. قَدْ رَعَى قَبْلَ ذَلِكَ أَرْبَعِينَ خَرِيفًا، فَأَرْسَلَ إِبْرَاهِيمُ ابْنَهُ وَاتَّبَعَ الْكَبْشَ، فَأَخْرَجَهُ إِلَى الْجَمْرَةِ الْأَوْلَى، فَرَمَاهُ بِسَبْعِ حَصَيَاتٍ فأفلَتَه عِنْدَهَا، فَجَاءَ الجمرةَ الْوُسْطَى فَأَخْرَجَهُ عِنْدَهَا، فَرَمَاهُ بِسَبْعِ حَصَيَاتٍ ثُمَّ أَفْلَتَهُ فَأَدْرَكَهُ عِنْدَ الْجَمْرَةِ الْكُبْرَى، فَرَمَاهُ بِسَبْعِ حَصَيَاتٍ فَأَخْرَجَهُ عِنْدَهَا.","w":"ابن كثير","en":"Ibn Kathir: Ibn Abbas said a ram came out for him from Paradise, which had grazed there forty years; Abraham's son chased it, and at the three Jamarat it escaped each time after he threw seven pebbles, until he caught it at the great Jamra."}]},{"id":"tayribrahim","ch":"rusul","t":"أربعة من الطير: طمأنينة القلب","e":"الطير الأربعة التي أراه الله بها كيف يحيي الموتى.","ay":[[2,260,260]],"q":[{"bk":"saadi","s":2,"ay":260,"x":"وأما البرهان الآخر فإن إبراهيم قال طالباً من الله أن يريه كيف يحيي الموتى فقال الله له: {أو لم تؤمن}؛ ليزيل الشبهة عن خليله، {قال}؛ إبراهيم:{بلى}؛ يا رب قد آمنت أنك على كل شيء قدير وأنك تحيي الموتى وتجازي العباد، ولكن أريد أن يطمئن قلبي وأصل إلى درجة عين اليقين، فأجاب الله دعوته كرامة له ورحمة بالعباد، {قال فخذ أربعة من الطير}؛ ولم يبين أي الطيور هي فالآية حاصلة بأي نوع منها وهو المقصود، {فصرهن إليك}؛ أي: ضمهن واذبحهن ومزقهن {ثم اجعل على كل جبل منهن جزءاً ثم ادعهن يأتينك سعياً واعلم أن الله عزيز حكيم}؛ ففعل ذلك وفرق أجزاءهن على الجبال التي حوله ودعاهن بأسمائهن فأقبلن إليه أي سريعات، لأن السعي السرعة، وليس المراد أنهن جئن على قوائمهن …","w":"السعدي","en":"Al-Sa'di: Abraham asked Allah to show him how He gives life to the dead; Allah said, 'Do you not believe?' He said, 'Yes, but so that my heart be at rest', to reach the level of certainty by sight. So Allah told him to take four birds, draw them to himself, cut them up, put a part on each mountain, then call them and they would come hurrying, and know that Allah is Mighty, Wise."},{"bk":"ibnkathir","s":2,"ay":260,"x":"وَقَوْلُهُ: ﴿قَالَ فَخُذْ أَرْبَعَةً مِنَ الطَّيْرِ فَصُرْهُنَّ إِلَيْكَ﴾ اخْتَلَفَ الْمُفَسِّرُونَ فِي هَذِهِ الْأَرْبَعَةِ: مَا هِيَ؟ وَإِنْ كَانَ لَا طَائِلَ تَحْتَ تَعْيِينِهَا، إِذْ لَوْ كَانَ فِي ذَلِكَ مُتَّهم لَنَصَّ عَلَيْهِ الْقُرْآنُ، فَرُوِيَ عَنِ ابْنِ عَبَّاسٍ أَنَّهُ قَالَ: هِيَ الْغُرْنُوقُ، وَالطَّاوُسُ، وَالدِّيكُ، وَالْحَمَامَةُ.","w":"ابن كثير","en":"Ibn Kathir: the exegetes differed on what the four birds were, though there is no benefit in identifying them, for had it mattered the Quran would have said so; Ibn Abbas said they were a crane, a peacock, a rooster and a dove."},{"bk":"qurtubi","s":2,"ay":260,"x":"فَأَخَذَ هذه الطير حسب ما أمر وذكاها ثُمَّ قَطَعَهَا قِطَعًا صِغَارًا، وَخَلَطَ لُحُومَ الْبَعْضِ إِلَى لُحُومِ الْبَعْضِ مَعَ الدَّمِ وَالرِّيشِ حَتَّى يَكُونَ أَعْجَبَ، ثُمَّ جَعَلَ مِنْ ذَلِكَ الْمَجْمُوعِ الْمُخْتَلِطِ جُزْءًا عَلَى كُلِّ جَبَلٍ، وَوَقَفَ هُوَ مِنْ حَيْثُ يَرَى تِلْكَ الْأَجْزَاءَ وَأَمْسَكَ رُءُوسَ الطَّيْرِ فِي يَدِهِ، ثُمَّ قَالَ: تَعَالَيْنَ بِإِذْنِ اللَّهِ، فَتَطَايَرَتْ تِلْكَ الْأَجْزَاءُ وَطَارَ الدَّمُ إِلَى الدَّمِ وَالرِّيشُ إِلَى الرِّيشِ حَتَّى الْتَأَمَتْ مِثْلَ مَا كَانَتْ أَوَّلًا وَبَقِيَتْ بِلَا رُءُوسٍ، ثُمَّ كَرَّرَ النِّدَاءَ فَجَاءَتْهُ سَعْيًا، أَيْ عَدْوًا عَلَى أَرْجُلِهِنَّ.","w":"القرطبي","en":"Al-Qurtubi: he took the birds as he was told, slaughtered and cut them into small pieces, mixed flesh, blood and feathers, put a portion on every mountain, stood where he could see them, and called 'Come by Allah's leave', and the parts flew together and the birds came running to him."}]},{"id":"tayrisa","ch":"rusul","t":"طير عيسى بإذن الله","e":"الطير الذي خلقه عيسى من الطين بإذن الله.","ay":[[3,49,49],[5,110,110]],"q":[{"bk":"saadi","s":3,"ay":49,"x":"وذلك {أني أخلق لكم من الطين كهيئة الطير فأنفخ فيه فيكون طيراً بإذن الله وأبرئ الأكمه}؛ وهو ممسوح العينين الذي فقد بصره وعيناه {والأبرص وأحيي الموتى بإذن الله وأنبئكم بما تأكلون وما تدخرون في بيوتكم، إن في ذلك}؛ المذكور {لآية لكم إن كنتم مؤمنين. ومصدقاً لما بين يدي من التوراة}؛ فأيده الله بجنسين من الآيات والبراهين الخوارق المستغربة التي لا يمكن لغير الأنبياء الإتيان بها، والرسالة والدعوة والدين الذي جاء به وأنه دين التوراة ودين الأنبياء السابقين، وهذا أكبر الأدلة على صدق الصادقين، فإنه لو كان من الكاذبين لخالف ما جاءت به الرسل ولناقضهم في أصولهم وفروعهم، فعلم بذلك أنه رسول الله وأن ما جاء به حق لا ريب فيه، وأيضاً فقوله:{ولأحل لكم بعض الذي حرم عليكم}؛ أي …","w":"السعدي","en":"Al-Sa'di: Jesus said he came with a sign from their Lord: that he would create for them from clay the shape of a bird, blow into it and it would be a bird by Allah's leave, heal the blind and the leper, give life to the dead by Allah's leave, and tell them what they eat and store in their houses; these were wonders only prophets could bring."},{"bk":"ibnkathir","s":3,"ay":49,"x":"وَقَوْلُهُ: ﴿وَرَسُولا إِلَى بَنِي إِسْرَائِيلَ﴾ أَيْ: [وَ] يَجْعَلُهُ رَسُولًا إِلَى بَنِي إِسْرَائِيلَ، قَائِلًا لَهُمْ: ﴿أَنِّي قَدْ جِئْتُكُمْ بِآيَةٍ مِنْ رَبِّكُمْ أَنِّي أَخْلُقُ لَكُمْ مِنَ الطِّينِ كَهَيْئَةِ الطَّيْرِ فَأَنْفُخُ فِيهِ فَيَكُونُ طَيْرًا بِإِذْنِ اللَّهِ﴾ وَكَذَلِكَ كَانَ يَفْعَلُ: يُصَوِّرُ مِنَ الطِّينِ شَكْلَ طَيْرٍ، ثُمَّ ينفخُ فِيهِ، فَيَطِيرُ عِيَانًا بِإِذْنِ اللَّهِ، عَزَّ وَجَلَّ، الَّذِي جَعَلَ هَذَا مُعْجِزَةً يَدُلّ عَلَى أَنَّ اللَّهَ أَرْسَلَهُ. ﴿وَأُبْرِئُ الأكْمَهَ﴾ قِيلَ: هُوَ الَّذِي يُبْصِرُ نَهَارًا وَلَا يُبْصِرُ لَيْلًا.","w":"ابن كثير","en":"Ibn Kathir: he would shape a bird from clay, then blow into it and it would fly before their eyes by Allah's leave, a miracle by which Allah made it clear that He had sent him."}]},{"id":"tayrdawud","ch":"rusul","t":"الطير المسخّرة لداود وسليمان","e":"تسخير الطير والجبال لداود، وتعليم سليمان منطق الطير.","ay":[[38,17,19],[34,10,10],[27,16,17]],"q":[{"bk":"saadi","s":38,"ay":19,"x":"ومن شدة إنابته لربِّه وعبادتِهِ أن سَخَّرَ الله الجبال معه تسبِّحُ معه بحمدِ ربِّها {بالعشيِّ والإشراقِ}: أول النهار وآخره، {و} سخَّر {الطيرَ محشورةً}: معه مجموعةً. {كلٌّ}: من الجبال والطير {له} تعالى {أوابٌ}: امتثالاً لقوله تعالى: {يا جبالُ أوِّبي معه والطير}: فهذه منَّةُ الله عليه بالعبادة.","w":"السعدي","en":"Al-Sa'di: out of David's great turning to his Lord and his worship, Allah subjected the mountains to glorify with him at evening and sunrise, and the birds gathered, all of them turning to Him; this was Allah's favour on him in worship."},{"bk":"ibnkathir","s":38,"ay":19,"x":"وَلِهَذَا قَالَ: ﴿وَالطَّيْرَ مَحْشُورَةً﴾ أَيْ: مَحْبُوسَةً فِي الْهَوَاءِ، ﴿كُلٌّ لَهُ أَوَّابٌ﴾ أَيْ: مُطِيعٌ يُسَبِّحُ تَبَعًا لَهُ. قَالَ سَعِيدُ بْنُ جُبَيْرٍ وَقَتَادَةُ وَمَالِكٌ عَنْ زَيْدِ بْنِ أَسْلَمَ وَابْنِ زَيْدٍ: ﴿كُلٌّ لَهُ أَوَّابٌ﴾ أَيْ: مُطِيعٌ.","w":"ابن كثير","en":"Ibn Kathir: 'the birds gathered' means held in the air, 'all were turning to Him' means obedient, glorifying with him; Sa'id ibn Jubayr, Qatada and others said 'turning' means obedient."},{"bk":"saadi","s":27,"ay":16,"x":"شكراً لله وتبجُّحاً بإحسانه وتحدُّثاً بنعمتِهِ: {يا أيُّها الناس عُلِّمۡنا منطقَ الطيرِ}: فكان عليه الصلاة والسلام يفقهُ ما تقولُ وتتكلمُ به؛ كما راجعَ الهدهدَ وراجَعَه، وكما فهم قول النملةِ للنمل كما يأتي، وهذا لم يكن لأحدٍ غير سليمان عليه السلام، {وأوتينا من كلِّ شيءٍ}؛ أي: أعطانا الله من النعم ومن أسباب الملك ومن السلطنة والقهر ما لم يؤتِ أحداً من الآدميين، ولهذا دعا ربَّه، فقال:{ربِّ هَبۡ لي ملكاً لا ينبغي لأحدٍ من بعدي}: فسخَّر الله له الشياطينَ يَعْمَلونَ له كلَّ ما شاء من الأعمال التي يَعْجَزُ عنها غيرُهم، وسخَّر له الريح غُدُوُّها شهرٌ ورَواحها شهرٌ. {إنَّ هذا}: الذي أعطانا الله، وفضَّلنا، واختصَّنا به {لهو الفضلُ المبين}: الواضح الجليُّ، فاعترف أكمل اعترافٍ بنعمة الله تعالى.","w":"السعدي","en":"Al-Sa'di: Solomon said, in thanks, 'O people, we were taught the speech of birds'; he understood what they said, as he conversed with the hoopoe and understood the ant, which was given to no one but him. He acknowledged Allah's favour fully: 'this is the clear favour'."}]},{"id":"himar","ch":"rusul","t":"الحمار: حياة بعد مئة عام","e":"الرجل الذي أماته الله مئة عام ثم بعثه وبعث حماره.","ay":[[2,259,259]],"q":[{"bk":"saadi","s":2,"ay":259,"x":"وذلك من آيات قدرة الله فإن الطعام والشراب خصوصاً ما ذكره المفسرون أنه فاكهة وعصير لا يلبث أن يتغير وهذا قد حفظه الله مئة عام وقيل له:{انظر إلى حمارك}؛ فإذا هو قد تمزق وتفرق وصار عظاماً نخرة، {وانظر إلى العظام كيف ننشزها}؛ أي: نرفع بعضها إلى بعض ونصل بعضها ببعض بعدما تفرقت وتمزقت {ثم نكسوها}؛ بعد الالتئام {لحماً}؛ ثم نعيد فيه الحياة {فلما تبين له}؛ رأيَ عين لا يقبل الريب بوجه من الوجوه {قال أعلم أن الله على كل شيء قدير}؛ فاعترف بقدرة الله على كل شيء وصار آية للناس، لأنهم قد عرفوا موته وموت حماره وعرفوا قضيته ثم شاهدوا هذه الآية الكبرى. هذا هو الصواب في هذا الرجل.","w":"السعدي","en":"Al-Sa'di: among Allah's signs of power, food and drink that quickly spoil were kept for a hundred years; he was told to look at his donkey, which had become decayed bones, and at the bones, how We raise and join them then clothe them with flesh. When it was clear to him he said, 'I know that Allah is Able over everything', and he became a sign for people."},{"bk":"ibnkathir","s":2,"ay":259,"x":"فَلَمَّا اسْتَقَلَّ سَوِيًّا قَالَ اللَّهُ لَهُ -أَيْ بِوَاسِطَةِ الْمَلَكِ-: ﴿كَمْ لَبِثْتَ قَالَ لَبِثْتُ يَوْمًا أَوْ بَعْضَ يَوْم﴾ قَالُوا: وَذَلِكَ أَنَّهُ مَاتَ أَوَّلَ النَّهَارِ ثُمَّ بَعَثَهُ اللَّهُ فِي آخِرِ نَهَارٍ، فَلَمَّا رَأَى الشَّمْسَ بَاقِيَةً ظَنَّ أَنَّهَا شَمْسُ ذَلِكَ الْيَوْمِ فَقَالَ: ﴿أَوْ بَعْضَ يَوْمٍ قَالَ بَلْ لَبِثْتَ مِائَةَ عَامٍ فَانْظُرْ إِلَى طَعَامِكَ وَشَرَابِكَ لَمْ يَتَسَنَّهْ﴾ وَذَلِكَ: أَنَّهُ كَانَ مَعَهُ فِيمَا ذُكِرَ عِنَبٌ وَتِينٌ وَعَصِيرٌ فَوَجَدَهُ كَمَا فَقَدَهُ لَمْ يَتَغَيَّرْ مِنْهُ شَيْءٌ، لَا الْعَصِيرُ اسْتَحَالَ وَلَا التِّينُ حَمِضَ وَلَا أَنْتَنَ وَلَا الْعِنَبُ تَعَفَّنَ ﴿وَانْظُرْ إِلَى حِمَارِك﴾ أَيْ: كَيْفَ يُحْيِيهِ اللَّهُ عَزَّ وَجَلَّ وَأَنْتَ تَنْظُرُ ﴿وَلِنَجْعَلَكَ آيَةً لِلنَّاسِ﴾ أَيْ: دَلِيلًا عَلَى الْمَعَادِ ﴿وَانْظُرْ إِلَى الْعِظَامِ كَيْفَ نُنْشِزُهَا﴾ أَيْ: نَرْفَعُهَا فَتَرْكَبُ بَعْضُهَا عَلَى بَعْضٍ …","w":"ابن كثير","en":"Ibn Kathir: when he rose upright Allah asked, 'How long did you stay?' He said a day or part of a day; Allah said a hundred years. His food and drink had not spoiled, and he was told to look at his donkey, how Allah brings it back to life before his eyes, to make him a sign for people and proof of resurrection, and at the bones, how We raise them."}]},{"id":"hayya","ch":"rusul","t":"عصا موسى حيّة تسعى","e":"العصا التي صارت حية تسعى آيةً لموسى.","ay":[[20,17,21],[7,107,107],[26,32,32]],"q":[{"bk":"saadi","s":20,"ay":20,"x":"{فألقاها فإذا هي حيَّةٌ تسعى}: انقلبت بإذن الله ثعباناً عظيماً، فولَّى موسى هارباً خائفاً ولم يعقبْ. وفي وصفها بأنها تسعى إزالةٌ لوهم يمكن وجوده، وهو أنْ يُظنَّ أنها تخييلٌ لا حقيقة؛ فكونها تسعى يزيلُ هذا الوهم.","w":"السعدي","en":"Al-Sa'di: he threw it and it was a serpent moving; it turned by Allah's leave into a great snake and Moses turned back in fear. The description 'moving' removes any thought that it was an illusion, since moving shows it was real."},{"bk":"ibnkathir","s":20,"ay":20,"x":"وَقَوْلُهُ تَعَالَى: ﴿ [قَالَ] أَلْقِهَا يَا مُوسَى﴾ أَيْ: هَذِهِ الْعَصَا الَّتِي فِي يَدِكَ يَا مُوسَى، أَلْقِهَا ﴿فَأَلْقَاهَا فَإِذَا هِيَ حَيَّةٌ تَسْعَى﴾ أَيْ: صَارَتْ فِي الْحَالِ حَيَّة عَظِيمَةً، ثُعْبَانًا طَوِيلًا يَتَحَرَّكُ حَرَكَةً سَرِيعَةً، فَإِذَا هِيَ تَهْتَزُّ كَأَنَّهَا جَانٌّ، وَهُوَ أَسْرَعُ الْحَيَّاتِ حَرَكَةً، وَلَكِنَّهُ صَغِيرٌ، فَهَذِهِ فِي غَايَةِ الْكُبْرِ، وَفِي غَايَةِ سُرْعَةِ الْحَرَكَةِ، ﴿تَسْعَى﴾ أَيْ: تَمْشِي وَتَضْطَرِبُ.","w":"ابن كثير","en":"Ibn Kathir: the staff in his hand at once became a huge, long serpent moving swiftly, quivering like a small snake, the fastest of snakes, but this one was extremely large and extremely fast."}]},{"id":"khayl","ch":"rusul","t":"الخيل الصافنات وسليمان","e":"عرض الخيل الصافنات على سليمان وما قاله.","ay":[[38,30,33]],"q":[{"bk":"saadi","s":38,"ay":31,"x":"ولهذا؛ لما عُرِضَتِ [عليه] الخيل الجياد السبق {الصافناتُ}؛ أي: التي من وصفها الصُّفونُ، وهو رفع إحدى قوائِمِها عند الوقوف، وكان لها منظرٌ رائقٌ وجمالٌ معجبٌ، خصوصاً للمحتاج إليها؛ كالملوك؛ فما زالتْ تُعْرَضُ عليه حتى غابتِ الشمس في الحجاب، فألهتْه عن صلاة المساءِ وذِكْرِهِ، فقال ندماً على ما مضى منه، وتقرُّباً إلى الله بما ألهاه عن ذكرِهِ، وتقديماً لحبِّ الله على حبِّ غيره:{إنِّي أحببتُ حُبَّ الخيرِ}: وضمَّنَ أحببتُ معنى آثرتُ؛ أي: آثرتُ حبَّ الخير الذي هو المالُ عموماً وفي الموضع المرادُ الخيل {عن ذِكۡرِ ربِّي حتى تَوارَتۡ بالحجابِ. ردُّوها عليَّ}: فردُّوها، {فطَفِقَ}: فيها {مسحاً بالسُّوقِ والأعناقِ}؛ أي: جعل يعقِرُها بسيفِهِ في سوقِها وأعناقها. {34}{ولقد فتنَّا سليمانَ}؛ أي: ابتليْناه واختبرْناه بذَهابِ ملكِهِ وانفصالِهِ عنه بسبب خلل اقتضتْه الطبيعةُ البشريةُ …","w":"السعدي","en":"Al-Sa'di: when the fine, swift standing horses were shown to him, with a lovely sight especially to kings, they kept being shown until the sun was hidden and distracted him from his evening prayer and remembrance; out of regret he put love of Allah first, said 'I preferred the love of good things to the remembrance of my Lord', had them brought back and began to cut at their legs and necks with his sword."},{"bk":"ibnkathir","s":38,"ay":31,"x":"وَقَوْلُهُ: ﴿إِذْ عُرِضَ عَلَيْهِ بِالْعَشِيِّ الصَّافِنَاتُ الْجِيَادُ﴾ أَيْ: إِذْ عُرِضَ عَلَى سُلَيْمَانَ فِي حَالِ مَمْلَكَتِهِ وَسُلْطَانِهِ الْخَيْلُ الصَّافِنَاتُ. قَالَ مُجَاهِدٌ: وَهِيَ الَّتِي تَقِفُ عَلَى ثَلَاثٍ وَطَرَفِ حَافِرِ الرَّابِعَةِ، وَالْجِيَادُ: السِّرَاعُ. وَكَذَا قَالَ غَيْرُ وَاحِدٍ مِنَ السَّلَفِ.","w":"ابن كثير","en":"Ibn Kathir: 'the standing horses' were shown to Solomon at evening in the time of his kingdom; Mujahid said they stand on three legs with the tip of the fourth hoof, and 'swift' means fast, as several of the early scholars said."}]},{"id":"baqara","ch":"rusul","t":"البقرة: التسليم لأمر الله بلا تعنّت","e":"أمر بني إسرائيل بذبح بقرة وتكرار سؤالهم عن صفتها.","ay":[[2,67,73]],"q":[{"bk":"saadi","s":2,"ay":67,"x":"أي: واذكروا ما جرى لكم مع موسى حين قتلتم قتيلاً؛ فادّارَأْتم فيه، أي: تدافعتم واختلفتم في قاتله حتى تفاقم الأمر بينكم، وكاد ـ لولا تبيين الله لكم ـ يحدث بينكم شر كبير، فقال لكم موسى في تبيين القاتل: اذبحوا بقرة، وكان من الواجب المبادرة إلى امتثال أمره وعدم الاعتراض عليه، ولكنهم أبوا إلا الاعتراض فقالوا:{أتتخذنا هزواً}؛ فقال نبي الله:{أعوذ بالله أن أكون من الجاهلين}؛ فإن الجاهل هو الذي يتكلم بالكلام الذي لا فائدة فيه وهو الذي يستهزئ بالناس، وأما العاقل فيرى أن من أكبر العيوب المزرية بالدين والعقل استهزاءه بمن هو آدمي مثله. وإن كان قد فضل عليه فتفضيله يقتضي منه الشكر لربه والرحمة لعباده: فلما قال لهم موسى ذلك علموا أن ذلك صدق، فقالوا …","w":"السعدي","en":"Al-Sa'di: remember what happened with Moses when you killed a man and disputed over the killer; Moses told them to slaughter a cow, and the duty was to hurry to obey without objecting, yet they objected, saying 'Do you mock us?' He said, 'I seek refuge in Allah from being among the ignorant', for the ignorant speaks what has no use and mocks people, while the wise sees mocking someone like himself as a great flaw."},{"bk":"ibnkathir","s":2,"ay":68,"x":"وَلِهَذَا لَمَّا ضَيَّقُوا عَلَى أَنْفُسِهِمْ ضُيِّقَ عَلَيْهِمْ، وَلَوْ أَنَّهُمْ ذَبَحُوا أَيَّ بَقَرَةٍ كَانَتْ لَوَقَعَتِ الْمَوْقِعَ عَنْهُمْ، كَمَا قَالَ ابْنُ عَبَّاسٍ وَعُبَيْدَةُ وَغَيْرُ وَاحِدٍ، وَلَكِنَّهُمْ شَدَّدُوا فَشُدِّدَ عَلَيْهِمْ، فَقَالُوا: ﴿ادْعُ لَنَا رَبَّكَ يُبَيِّنْ لَنَا مَا هِيَ﴾ مَا هَذِهِ الْبَقَرَةُ؟ وَأَيُّ شَيْءٍ صِفَتُهَا؟","w":"ابن كثير","en":"Ibn Kathir: when they made things hard for themselves it was made hard for them; had they slaughtered any cow it would have sufficed, as Ibn Abbas and others said, but they were strict and so were made to face strictness, and they said, 'Ask your Lord to make clear to us what it is.'"}]},{"id":"kalbkahf","ch":"rusul","t":"كلب أصحاب الكهف","e":"الكلب الباسط ذراعيه بالوصيد عند فتية الكهف.","ay":[[18,18,18],[18,22,22]],"q":[{"bk":"saadi","s":18,"ay":18,"x":"أي: الكلب الذي كان مع أصحابِ الكهف أصابَهُ ما أصابَهم من النوم وقتَ حراستِهِ، فكان باسطاً ذراعيه بالوصيد؛ أي: الباب أو فنائه.","w":"السعدي","en":"Al-Sa'di: the dog with the companions of the cave was struck by the sleep that struck them while on guard, stretching his forelegs at the threshold, meaning the door or its yard."},{"bk":"ibnkathir","s":18,"ay":18,"x":"وَهَذَا مِنْ سَجِيَّتِهِ وَطَبِيعَتِهِ، حَيْثُ يَرْبِضُ بِبَابِهِمْ كَأَنَّهُ يَحْرُسُهُمْ، وَكَانَ جُلُوسُهُ خَارِجَ الْبَابِ؛ لِأَنَّ الْمَلَائِكَةَ لَا تَدْخُلُ بَيْتًا فِيهِ كَلْبٌ -كَمَا وَرَدَ فِي الصَّحِيحِ -وَلَا صُورَةٌ وَلَا جُنُب وَلَا كَافِرٌ، كَمَا وَرَدَ بِهِ الْحَدِيثُ الْحَسَنُ وَشَمَلَتْ كَلْبَهُمْ بَرَكَتُهُمْ، فَأَصَابَهُ مَا أَصَابَهُمْ مِنَ النَّوْمِ عَلَى تِلْكَ الْحَالِ.","w":"ابن كثير","en":"Ibn Kathir: this is his nature, lying at their door as if guarding them, sitting outside because angels do not enter a house with a dog, as in the Sahih, nor with images, a person in major impurity or a disbeliever; their blessing reached their dog, so what struck them of sleep struck him."},{"bk":"qurtubi","s":18,"ay":18,"x":"أَكْثَرُ الْمُفَسِّرِينَ عَلَى أَنَّهُ كَلْبٌ حَقِيقَةً، وَكَانَ لِصَيْدِ أَحَدِهِمْ أَوْ لِزَرْعِهِ أَوْ غَنَمِهِ، عَلَى مَا قَالَ مُقَاتِلٌ. وَاخْتُلِفَ فِي لَوْنِهِ اخْتِلَافًا كَثِيرًا، ذَكَرَهُ الثَّعْلَبِيُّ.","w":"القرطبي","en":"Al-Qurtubi: most exegetes hold that it was a real dog, belonging to one of them for hunting, crops or sheep, as Muqatil said; there was much disagreement over its colour, which al-Tha'labi mentioned."}]},{"id":"fil","ch":"ayat","t":"الفيل والطير الأبابيل","e":"إهلاك الله أصحاب الفيل بطير أبابيل.","ay":[[105,1,5]],"q":[{"bk":"saadi","s":105,"ay":1,"x":"وهي مكية بِسْمِ اللَّهِ الرَّحْمَنِ الرَّحِيمِ {1 ـ 5} أي: أما رأيتَ من قدرة الله وعظيم شأنه ورحمته بعباده وأدلَّة توحيده وصدق رسوله [محمدٍ]- صلى الله عليه وسلم - ما فعله اللهُ بأصحاب الفيل، الذين كادوا بيتَه الحرام، وأرادوا إخرابه؛ فتجهَّزوا لأجل ذلك، واستصحبوا معهم الفِيَلَةَ لهدمه، وجاؤوا بجمعٍ لا قِبَلَ للعرب به من الحبشة واليمن، فلما انتهَوْا إلى قربِ مكَّةَ ـ ولم يكن بالعرب مدافعةٌ، وخرج أهل مكَّة من مكَّة خوفاً [على أنفسهم] منهم ـ أرسل الله عليهم طيراً أبابيلَ؛ أي: متفرِّقة، تحمل أحجاراً محمَّاة من سِجِّيلٍ، فرمتْهم بها، وتتبَّعَتْ قاصِيَهم ودانِيَهم، فخمدوا وهمدوا، وصاروا كعصفٍ مأكولٍ، وكفى الله شرَّهم، وردَّ كيدهم في نحورهم، وقصَّتُهم معروفةٌ مشهورةٌ …","w":"السعدي","en":"Al-Sa'di: have you not seen what Allah did to the people of the elephant, who plotted against His Sacred House and brought elephants to destroy it with a force the Arabs could not face; Allah sent swarming birds carrying baked clay stones, which struck them and pursued near and far until they were like eaten straw, and Allah spared people their evil."},{"bk":"ibnkathir","s":105,"ay":3,"x":"فَبَيْنَمَا هُمْ كَذَلِكَ، إِذْ بَعَثَ اللَّهُ عَلَيْهِمْ طَيْرًا أَبَابِيلَ، أَيْ قَطَعًا قِطَعًا صُفْرًا دُونَ الْحَمَامِ، وَأَرْجُلُهَا حُمْرٌ، وَمَعَ كُلِّ طَائِرٍ ثَلَاثُ أَحْجَارٍ، وَجَاءَتْ فَحَلَّقَتْ عَلَيْهِمْ، وَأَرْسَلَتْ تِلْكَ الْأَحْجَارَ عَلَيْهِمْ فَهَلَكُوا. وَقَالَ مُحَمَّدُ بْنُ كَعْبٍ: جَاءُوا بِفِيلَيْنِ فَأَمَّا مَحْمُودٌ فَرَبض، وَأَمَّا الْآخَرُ فَشَجُع فحُصِب.","w":"ابن كثير","en":"Ibn Kathir: while they were so, Allah sent against them swarming birds, in flocks, yellowish and smaller than doves, red-legged, each carrying three stones; they circled over them, dropped the stones, and they perished. Muhammad ibn Ka'b said they brought two elephants, one knelt down and the other advanced and was pelted."}]},{"id":"jarad","ch":"ayat","t":"الجراد والقمل والضفادع آيات مفصلات","e":"الجراد والقمل والضفادع من آيات موسى لفرعون.","ay":[[7,133,133]],"q":[{"bk":"saadi","s":7,"ay":133,"x":"{فأرسلنا عليهم الطوفان}؛ أي: الماء الكثير الذي أغرق أشجارهم وزروعهم وأضرَّهم ضرراً كثيراً، {والجراد}: فأكل ثمارَهم وزروعَهم ونباتهم، {والقُمَّلَ}: قيل: إنه الدُّباء؛ أي: صغار الجراد، والظاهر أنه القمل المعروف، {والضفادع}: فملأت أوعيتهم وأقلقتهم وآذتهم أذيَّة شديدةً، {والدم}: إما أن يكونَ الرعاف، أو كما قال كثير من المفسرين: إنَّ ماءهم الذي يشربون انقلب دماً، فكانوا لا يشربون إلاَّ دماً ولا يطبخون [إلاّ بدم]. {آياتٍ مفصَّلاتٍ}؛ أي: أدلَّة وبيِّنات على أنَّهم كانوا كاذبين ظالمين، وعلى أن ما جاء به موسى حقٌّ وصدقٌ.","w":"السعدي","en":"Al-Sa'di: Allah sent the flood that drowned their trees and crops, then locusts that ate their fruits and crops, lice (or, it is said, young locusts), frogs that filled their vessels and tormented them, and blood, as detailed signs that they were wrongdoers and that what Moses brought was true."},{"bk":"ibnkathir","s":7,"ay":133,"x":"[فَأَصْبَحَتْ كَالصَّرِيمِ] ﴾ [القلم:١٩، ٢٠] وَأَمَّا الْجَرَادُ فَمَعْرُوفٌ مَشْهُورٌ، وَهُوَ مَأْكُولٌ؛ لِمَا ثَبَتَ فِي الصَّحِيحَيْنِ عَنْ أَبِي يعفُور قَالَ: سَأَلْتُ عَبْدَ اللَّهِ بْنَ أَبِي أَوْفَى عَنِ الْجَرَادِ، فَقَالَ: غَزَوْنَا مَعَ رَسُولِ اللَّهِ ﷺ سَبْعَ غَزَوَاتٍ نَأْكُلُ الْجَرَادَ وَرَوَى الشَّافِعِيُّ، وَأَحْمَدُ بْنُ حَنْبَلٍ، وَابْنُ مَاجَهْ مِنْ حَدِيثِ عَبْدِ الرَّحْمَنِ بْنِ زَيْدِ بْنِ أَسْلَمَ، عَنْ أَبِيهِ، عَنِ ابْنِ عُمَرَ، عَنِ النَّبِيِّ ﷺ قَالَ: \"أُحِلَّتْ لَنَا مَيْتَتَانِ وَدَمَانِ: الْحُوتُ وَالْجَرَادُ، وَالْكَبِدُ وَالطِّحَالُ\" وَرَوَاهُ أَبُو الْقَاسِمِ الْبَغَوِيُّ، عَنْ دَاوُدَ بْنِ رُشَيْد، عَنْ سُوَيْد بْنِ عَبْدِ الْعَزِيزِ، عَنْ أَبِي تَمَّامٍ الْأَيْلِيِّ، عَنْ زَيْدِ بْنِ أَسْلَمَ، عَنِ ابْنِ عُمَرَ مَرْفُوعًا مِثْلَهُ وَرَوَى أَبُو دَاوُدَ، عَنْ مُحَمَّدِ بْنِ الْفَرَجِ، عَنْ مُحَمَّدِ بْنِ الزِّبْرِقان الْأَهْوَازِيِّ، عَنْ سُلَيْمَانَ التَّيْمِيِّ، عَنْ أَبِي عُثْمَانَ، عَنْ سَلْمَانَ قَالَ …","w":"ابن كثير","en":"Ibn Kathir: locusts are well known and are eaten, as in the two Sahihs, from Ibn Abi Awfa who said they fought seven campaigns with the Messenger of Allah eating locusts; he also reports the hadith 'Two dead animals and two bloods are made lawful for us: fish and locusts, the liver and the spleen', with the discussion of its chains."}]},{"id":"daabba","ch":"ayat","t":"دابة الأرض من أشراط الساعة","e":"الدابة التي تخرج للناس قرب الساعة.","ay":[[27,82,82]],"q":[{"bk":"saadi","s":27,"ay":82,"x":"أي: إذا وقع على الناس {القولُ} الذي حَتَّمهُ الله وفرضَ وقته؛ {أخرجنا لهم دابَّةً} خارجةً {من الأرض}، أو دابةً من دوابِّ الأرض، ليست من السماء، وهذه الدابَّة {تكلِّمهم}؛ أي: تكلِّم العباد {أنَّ الناس كانوا بآياتنا لا يوقنون}؛ أي: لأجل أنَّ الناس ضَعُفَ علمهم ويقينهم بآيات الله؛ فإظهار الله هذه الدابة من آياتِ الله العجيبة؛ ليبيِّن للناس ما كانوا فيه يمترون. وهذه الدابَّة المشهورة التي تخرج في آخر الزمان، وتكون من أشراط الساعة؛ كما تكاثرت بذلك الأحاديث ، [لم يذكر الله ورسوله كيفيَّة هذه الدابة، وإنَّما ذكر أثرها والمقصود منها، وأنَّها من آيات الله؛ تكلِّم الناسَ كلاماً خارقاً للعادة حين يقعُ القول على الناس وحين يمترونَ بآياتِ الله، فتكون حجَّة وبرهاناً للمؤمنين، وحجَّة على المعاندين].","w":"السعدي","en":"Al-Sa'di: when the word falls on people Allah will bring out for them a beast from the earth that will speak to them that people did not have certainty in Allah's signs; it is the famous beast that comes at the end of time, among the signs of the Hour, and Allah did not describe how it is, only its effect and its aim."},{"bk":"ibnkathir","s":27,"ay":82,"x":"هَذِهِ الدَّابَّةُ تَخْرُجُ فِي آخِرِ الزَّمَانِ عِنْدَ فَسَادِ النَّاسِ وتَرْكِهم أَوَامِرَ اللَّهِ وَتَبْدِيلِهِمُ الدِّينَ الْحَقَّ، يُخْرِجُ اللَّهُ لَهُمْ دَابَّةً مِنَ الْأَرْضِ -قِيلَ: مِنْ مَكَّةَ.","w":"ابن كثير","en":"Ibn Kathir: this beast comes out at the end of time when people are corrupt, leave Allah's commands and change the true religion; Allah brings out for them a beast from the earth, some say from Mecca."}]},{"id":"kalb","ch":"amthal","t":"مثل الكلب: لهث الحريص على الدنيا","e":"تشبيه من آتاه الله آياته فانسلخ منها بالكلب اللاهث.","ay":[[7,175,176]],"q":[{"bk":"saadi","s":7,"ay":176,"x":"في شدة حرصه على الدنيا وانقطاع قلبه إليها {كمثل الكلب إن تَحۡمِلۡ عليه يَلۡهَثۡ أو تترُكۡهُ يلهثۡ}؛ أي: لا يزال لاهثاً في كل حال، وهذا لا يزال حريصاً حرصاً قاطعاً قلبه لا يسدُّ فاقتَهُ شيءٌ من الدُّنيا. {ذلك مَثَلُ القوم الذين كذَّبوا بآياتنا}: بعد أن ساقها الله إليهم، فلم ينقادوا لها، بل كذَّبوا بها وردُّوها لهوانهم على الله واتِّباعهم لأهوائهم بغير هدى من الله.","w":"السعدي","en":"Al-Sa'di: his likeness, in his intense greed for this world and his heart's attachment to it, is that of the dog: if you drive him off he pants, if you leave him he pants; always panting, he is so greedy that nothing of the world fills his need. That is the likeness of those who denied Our signs."},{"bk":"ibnkathir","s":7,"ay":176,"x":"وَقِيلَ: مَعْنَاهُ: فَصَارَ مِثْلَهُ فِي ضَلَالِهِ وَاسْتِمْرَارِهِ فِيهِ، وَعَدَمِ انْتِفَاعِهِ بِالدُّعَاءِ إِلَى الْإِيمَانِ وَعَدَمِ الدُّعَاءِ، كَالْكَلْبِ فِي لَهْثِهِ فِي حَالَتَيْهِ، إن حَمَلْتَ عَلَيْهِ وَإِنَّ تَرِكْتَهُ، هُوَ يَلْهَثُ فِي الْحَالَيْنِ، فَكَذَلِكَ هَذَا لَا يَنْتَفِعُ بِالْمَوْعِظَةِ وَالدَّعْوَةِ إِلَى الْإِيمَانِ وَلَا عَدَمِهِ؛ كَمَا قَالَ تَعَالَى: ﴿سَوَاءٌ عَلَيْهِمْ أَأَنْذَرْتَهُمْ أَمْ لَمْ تُنْذِرْهُمْ لَا يُؤْمِنُونَ﴾ [الْبَقَرَةِ:٦] ، ﴿اسْتَغْفِرْ لَهُمْ أَوْ لَا تَسْتَغْفِرْ لَهُمْ إِنْ تَسْتَغْفِرْ لَهُمْ سَبْعِينَ مَرَّةً فَلَنْ يَغْفِرَ اللَّهُ لَهُمْ﴾ [التَّوْبَةِ:٨٠] وَنَحْوَ ذَلِكَ.","w":"ابن كثير","en":"Ibn Kathir: it is also said it means he became like the dog in his error and persistence, not benefiting from the call to faith or its absence, like the dog panting in both states; so this one does not benefit from admonition, as in 'it is the same whether you warn them or not'."}]},{"id":"himarasfar","ch":"amthal","t":"مثل الحمار يحمل أسفاراً","e":"تشبيه الذين حُمّلوا التوراة ثم لم يحملوها بالحمار.","ay":[[62,5,5]],"q":[{"bk":"ibnkathir","s":62,"ay":5,"x":"وَكَذَلِكَ هَؤُلَاءِ فِي حَمْلِهِمُ الْكِتَابَ الَّذِي أُوتُوهُ، حَفِظُوهُ لَفْظًا وَلَمْ يَفْهَمُوهُ وَلَا عَمِلُوا بِمُقْتَضَاهُ، بَلْ أَوَّلُوهُ وَحَرَّفُوهُ وَبَدَّلُوهُ، فَهُمْ أَسْوَأُ حَالًا مِنَ الْحَمِيرِ؛ لِأَنَّ الْحِمَارَ لَا فهمَ لَهُ، وَهَؤُلَاءِ لَهُمْ فُهُومٌ لَمْ يَسْتَعْمِلُوهَا؛ وَلِهَذَا قَالَ فِي الْآيَةِ الْأُخْرَى: ﴿أُولَئِكَ كَالأنْعَامِ بَلْ هُمْ أَضَلُّ أُولَئِكَ هُمُ الْغَافِلُونَ …","w":"ابن كثير","en":"Ibn Kathir: such are those who memorised the Book given to them without understanding or acting on it, even reinterpreting, distorting and altering it, so they are worse than donkeys, for a donkey has no understanding while they have minds they did not use; hence the other verse, 'they are like cattle, rather more astray'."},{"bk":"saadi","s":62,"ay":5,"x":"لمَّا ذكر تعالى منَّته على هذه الأمة الذين بَعَثَ فيهم النبيَّ الأميَّ وما خصَّهم الله [به] من المزايا والمناقب التي لا يلحقهم فيها أحدٌ، وهم الأمة الأميَّة، الذين فاقوا الأوَّلين والآخرين، حتى أهل الكتاب الذين يزعمون أنهم العلماء الربانيون والأحبار المتقدِّمون؛ ذكر أن الذين حمَّلهم الله التوراة من اليهود وكذا النصارى وأمرهم أن يتعلَّموها ويعملوا بها فلم يحملوها ولم يقوموا بما حُمِّلوا به؛ أنَّهم لا فضيلة لَهم، وأنَّ مَثَلَهم كمثل الحمار الذي يحمل فوق ظهره أسفاراً من كتب العلم؛ فهل يستفيد ذلك الحمار من تلك الكتب التي فوق ظهره؟! وهل تلحقه فضيلةٌ بسبب ذلك؟!","w":"السعدي","en":"Al-Sa'di: those entrusted with the Torah and told to learn and act on it, but who did not carry it out, have no merit; they are like the donkey carrying books of knowledge on its back; does it benefit from them, and does any merit reach it?"}]},{"id":"baooda","ch":"amthal","t":"البعوضة: لا يستحيي الحق أن يضرب المثل","e":"ضرب المثل بالبعوضة فما فوقها.","ay":[[2,26,26]],"q":[{"bk":"saadi","s":2,"ay":26,"x":"يقول تعالى: {إن الله لا يستحيي أن يضرب مثلاً ما}؛ أيْ: أيُّ مثل كان {بعوضة فما فوقها}؛ لاشتمال الأمثال على الحكمة وإيضاح الحق، والله لا يستحيي من الحق، وكأنّ في هذا جواباً لمن أنكر ضرب الأمثال في الأشياء الحقيرة، واعترض على الله في ذلك؛ فليس في ذلك محل اعتراض، بل هو من تعليم الله لعباده ورحمته بهم، فيجب أن تتلقى بالقبول والشكر، ولهذا قال:{فأما الذين آمنوا فيعلمون أنه الحق من ربهم}؛ فيفهمونها ويتفكرون فيها، فإن علموا ما اشتملت عليه على وجه التفصيل ازداد بذلك علمهم وإيمانهم، وإلا علموا أنها حق، وما اشتملت عليه حق، وإن خفي عليهم وجه الحق فيها، لعلمهم بأن الله لم يضربها عبثاً بل لحكمة بالغة ونعمة سابغة، {وأما الذين كفروا فيقولون ماذا أراد الله بهذا مثلاً} …","w":"السعدي","en":"Al-Sa'di: Allah is not shy to draw a parable of anything, a mosquito or more, because parables hold wisdom and clarify truth; it answers those who objected to parables about lowly things, for it is Allah's teaching and mercy to His servants, to be received with acceptance and thanks. The believers know it is the truth from their Lord, and if the detail is hidden they know that He does not draw parables in vain."},{"bk":"ibnkathir","s":2,"ay":26,"x":"وَقَالَ أَبُو الْعَالِيَةِ: ﴿فَأَمَّا الَّذِينَ آمَنُوا فَيَعْلَمُونَ أَنَّهُ الْحَقُّ مِنْ رَبِّهِمْ﴾ يَعْنِي: هَذَا الْمَثَلُ: ﴿وَأَمَّا الَّذِينَ كَفَرُوا فَيَقُولُونَ مَاذَا أَرَادَ اللَّهُ بِهَذَا مَثَلا﴾ كَمَا قَالَ فِي سُورَةِ الْمُدَّثِّرِ: ﴿وَمَا جَعَلْنَا أَصْحَابَ النَّارِ إِلا مَلائِكَةً وَمَا جَعَلْنَا عِدَّتَهُمْ إِلا فِتْنَةً لِلَّذِينَ كَفَرُوا لِيَسْتَيْقِنَ الَّذِينَ أُوتُوا الْكِتَابَ وَيَزْدَادَ الَّذِينَ آمَنُوا إِيمَانًا وَلا يَرْتَابَ الَّذِينَ أُوتُوا الْكِتَابَ وَالْمُؤْمِنُونَ وَلِيَقُولَ الَّذِينَ فِي قُلُوبِهِمْ مَرَضٌ وَالْكَافِرُونَ مَاذَا أَرَادَ اللَّهُ بِهَذَا مَثَلا كَذَلِكَ يُضِلُّ اللَّهُ مَنْ يَشَاءُ وَيَهْدِي مَنْ يَشَاءُ وَمَا يَعْلَمُ جُنُودَ رَبِّكَ إِلا هُوَ﴾ [الْمُدَّثِّرِ: ٣١] ، وَكَذَلِكَ قَالَ هَاهُنَا: ﴿يُضِلُّ بِهِ كَثِيرًا وَيَهْدِي بِهِ كَثِيرًا وَمَا يُضِلُّ بِهِ إِلا الْفَاسِقِينَ﴾ قَالَ السُّدِّيُّ فِي تَفْسِيرِهِ، عَنْ أَبِي مَالِكٍ وَعَنْ أَبِي صَالِحٍ، عَنِ ابْنِ عَبَّاسٍ -وَعَنْ مُرَّةَ، عَنِ ابْنِ مَسْعُودٍ، وَعَنْ نَاسٍ مِنَ الصَّحَابَةِ …","w":"ابن كثير","en":"Ibn Kathir: Abu al-Aliyah said that 'those who believe know it is the truth from their Lord' means this parable, and 'those who disbelieve say, What did Allah mean by this as a parable?', as in Surat al-Muddaththir, 'We made the number of the angels only a trial for those who disbelieve'."}]},{"id":"ankabut","ch":"amthal","t":"العنكبوت: أوهن البيوت","e":"تشبيه من اتخذ من دون الله أولياء ببيت العنكبوت.","ay":[[29,41,41]],"q":[{"bk":"saadi","s":29,"ay":41,"x":"هذا مثلٌ ضربه الله لمن عَبَدَ معه غيرَه يقصدُ به التعزُّز والتقوِّي والنفع، وأنَّ الأمر بخلاف مقصوده؛ فإنَّ مَثَلَه كمثل العنكبوت اتَّخذت بيتاً يقيها من الحرِّ والبرد والآفات، {وإنَّ أوهنَ البيوتِ}: أضعفها وأوهاها {لبيتُ العنكبوتِ}: فالعنكبوت من الحيوانات الضعيفة، وبيتُها من أضعف البيوت؛ فما ازدادتْ باتِّخاذه إلاَّ ضعفاً. كذلك هؤلاء الذين يتَّخذون من دونه أولياء فقراء عاجزون من جميع الوجوه، وحين اتَّخذوا الأولياء من دونه يتعزَّزون بهم ويستَنْصِرونهم؛ ازدادوا ضَعْفاً إلى ضعفهم ووهناً إلى وهنهم؛ فإنَّهم اتَّكلوا عليهم في كثير من مصالحهم، وألْقَوْها عليهم، وتخلَّوْا هم عنها؛ على أنَّ أولئك سيقومون بها، فخذلوهم، فلم يحصُلوا منهم على طائل، ولا أنالوهم من معونتهم أقلَّ نائل؛ فلو كانوا يعلمون حقيقة العلم حالهم وحال مَن اتَّخذوهم؛ لم يَتَّخِذوهم، ولتبرؤوا منهم …","w":"السعدي","en":"Al-Sa'di: this is a parable of those who worship others with Allah seeking strength and benefit, but the matter is contrary to their aim: they are like the spider that took a house to protect it from heat, cold and harm, and 'the frailest of houses is the spider's house'; the spider is weak and its house the weakest, so it gained only weakness; so too those who take protectors, who are poor and helpless, and gain only more weakness."},{"bk":"ibnkathir","s":29,"ay":41,"x":"هَذَا مَثَلٌ ضَرَبَهُ اللَّهُ تَعَالَى لِلْمُشْرِكِينَ فِي اتِّخَاذِهِمْ آلِهَةً مِنْ دُونِ اللَّهِ، يَرْجُونَ نَصْرَهُمْ وَرِزْقَهُمْ، وَيَتَمَسَّكُونَ بِهِمْ فِي الشَّدَائِدِ، فَهُمْ فِي ذَلِكَ كَبَيْتِ الْعَنْكَبُوتِ فِي ضَعْفِهِ وَوَهَنِهِ فَلَيْسَ فِي أَيْدِي هَؤُلَاءِ مِنْ آلِهَتِهِمْ إِلَّا كمَنْ يَتَمَسَّكُ بِبَيْتِ الْعَنْكَبُوتِ، فَإِنَّهُ لَا يُجْدِي عَنْهُ شَيْئًا، فَلَوْ عَلموا هَذَا الْحَالَ لَمَا اتَّخَذُوا مِنْ دُونِ اللَّهِ أَوْلِيَاءَ، وَهَذَا بِخِلَافِ الْمُسْلِمِ الْمُؤْمِنِ قَلْبُهُ لِلَّهِ، وَهُوَ مَعَ ذَلِكَ يُحْسِنُ الْعَمَلَ فِي اتِّبَاعِ الشَّرْعِ فَإِنَّهُ مُسْتَمْسِكٌ بِالْعُرْوَةِ الْوُثْقَى لَا انْفِصَامَ لَهَا، لِقُوَّتِهَا وَثَبَاتِهَا. ثُمَّ قَالَ تَعَالَى مُتَوَعِّدًا لِمَنْ عَبَدَ غَيْرَهُ وَأَشْرَكَ بِهِ: إِنَّهُ تَعَالَى يَعْلَمُ مَا هُمْ عَلَيْهِ مِنَ الْأَعْمَالِ، وَيَعْلَمُ مَا يُشْرِكُونَ بِهِ مِنَ الْأَنْدَادِ، وَسَيَجْزِيهِمْ وَصْفَهُمْ إِنَّهُ حَكِيمٌ عَلِيمٌ.","w":"ابن كثير","en":"Ibn Kathir: this is a parable for the polytheists in taking gods besides Allah, hoping for help and provision and clinging to them in hardship, who are like one holding a spider's house, which avails nothing; unlike the believing Muslim, whose heart is Allah's and who does good in following the Law, so he holds the firmest handhold that never breaks."}]},{"id":"dhubab","ch":"amthal","t":"الذباب: ضعف الطالب والمطلوب","e":"تحدّي من يدعون من دون الله أن يخلقوا ذباباً.","ay":[[22,73,74]],"q":[{"bk":"saadi","s":22,"ay":73,"x":"الذي هو المعبودُ من دون الله، {والمطلوبُ}: الذي هو الذباب؛ فكل منهما ضعيفٌ، وأضعفُ منهما من يتعلَّق بهذا الضعيف وينزِله منزلةَ ربِّ العالمين؛ فهذا ما قَدَر اللَّه حقَّ قدرِهِ، حيث سوَّى الفقيرَ العاجزَ من جميع الوجوه بالغنيِّ القويِّ من جميع الوجوه، سوَّى مَنْ لا يملِكُ لنفسه ولا لغيره نفعاً ولا ضرًّا ولا موتاً ولا حياةً ولا نشوراً بمن هو النافعُ الضارُّ المعطي المانعُ مالكُ الملكِ والمتصرِّفُ فيه بجميع أنواع التصريف.{إنَّ الله لَقَوِيٌ عزيزٌ}؛ أي: كامل القوة، كامل العزَّة، من كمال قوَّتِهِ وعزَّتِهِ: أنَّ نواصي الخلق بيديه، وأنَّه لا يتحرَّك متحرِّكٌ ولا يسكُنُ ساكنٌ إلاَّ بإرادتِهِ ومشيئتِهِ؛ فما شاء الله كان، وما لم يشأ لم يكن، ومن كمال قوَّتِهِ: أنه يمسِكُ السماواتِ والأرضَ أن تزولا، ومن كمال قوَّته …","w":"السعدي","en":"Al-Sa'di: 'weak are the seeker', the one worshipped besides Allah, 'and the sought', the fly; both are weak, and weaker still is the one who relies on this weak thing and puts it in the place of the Lord of the worlds; they did not esteem Allah as He deserves, equating the poor and helpless with the rich and mighty, the one who owns no benefit for himself with the Benefiter and Harmer. Allah is Strong, Mighty."},{"bk":"ibnkathir","s":22,"ay":73,"x":"هَذَا وَالذُّبَابُ مِنْ أَضْعَفِ مَخْلُوقَاتِ اللَّهِ وَأَحْقَرِهَا وَلِهَذَا [قَالَ: ﴿ضَعُفَ الطَّالِبُ وَالْمَطْلُوبُ﴾ ] .","w":"ابن كثير","en":"Ibn Kathir: the fly is among the weakest and humblest of Allah's creatures, hence 'weak are the seeker and the sought'."}]},{"id":"farash","ch":"amthal","t":"كالفراش المبثوث وكالجراد المنتشر","e":"وصف الناس يوم القيامة بالفراش المبثوث وبالجراد المنتشر.","ay":[[101,4,4],[54,6,8]],"q":[{"bk":"saadi","s":101,"ay":4,"x":"{يومَ يكونُ الناسُ}: من شدَّة الفزع والهول، {كالفراشِ المبثوثِ}؛ أي: كالجراد المنتشر الذي يموج بعضه في بعض، والفراش هي الحيوانات التي تكون في الليل يموج بعضها ببعض، لا تدري أين توجَّه؛ فإذا أوقد لها نارٌ؛ تهافتت إليها لضعف إدراكها، فهذه حال الناس أهل العقول. {5} وأما الجبال الصمُّ الصلابُ؛ فتكون {كالعهنِ المنفوشِ}؛ أي: كالصُّوف المنفوش الذي بقي ضعيفاً جدًّا تطير به أدنى ريح؛ قال تعالى:{وترى الجبال تحسبُها جامدةً وهي تمرُّ مرَّ السحابِ}، ثم بعد ذلك تكون هباءً منثوراً، فتضمحلُّ ولا يبقى منها شيءٌ يشاهَد.","w":"السعدي","en":"Al-Sa'di: on that day people, in the fear and terror, will be like scattered moths, meaning spreading locusts surging over each other; moths are night creatures that wander not knowing where, and when a fire is lit they throw themselves into it from weak perception; such is people's state. The firm mountains will be like fluffed wool, which any breeze carries away."},{"bk":"ibnkathir","s":101,"ay":4,"x":"ثُمَّ فَسَّرَ ذَلِكَ بِقَوْلِهِ: ﴿يَوْمَ يَكُونُ النَّاسُ كَالْفَرَاشِ الْمَبْثُوثِ﴾ أَيْ: فِي انْتِشَارِهِمْ وَتَفَرُّقِهِمْ، وَذَهَابِهِمْ وَمَجِيئِهِمْ، مِنْ حَيْرَتِهِمْ مِمَّا هُمْ فِيهِ، كَأَنَّهُمْ فَرَاشٌ مَبْثُوثٌ كَمَا قَالَ فِي الْآيَةِ الْأُخْرَى: ﴿كَأَنَّهُمْ جَرَادٌ مُنْتَشِرٌ﴾ * * وَقَوْلُهُ: ﴿وَتَكُونُ الْجِبَالُ كَالْعِهْنِ الْمَنْفُوشِ﴾ يَعْنِي: قَدْ صَارَتْ كَأَنَّهَا الصُّوفُ الْمَنْفُوشُ، الَّذِي قَدْ شَرَع فِي الذَّهَابِ وَالتَّمَزُّقِ. قَالَ مُجَاهِدٍ، وَعِكْرِمَةَ، وَسَعِيدِ بْنِ جُبَيْرٍ، وَالْحَسَنِ، وَقَتَادَةَ، وَعَطَاءٌ الْخُرَاسَانِيُّ، وَالضَّحَّاكُ، وَالسُّدِّيُّ: \" الْعِهْنِ\" الصُّوفُ.","w":"ابن كثير","en":"Ibn Kathir: it explains by 'the day when people will be like scattered moths', that is in their spreading and dispersing, coming and going, from their bewilderment, as in another verse, 'as if they were spreading locusts'; and the mountains will be like fluffed wool, the wool starting to go and tear apart."}]},{"id":"qirada","ch":"amthal","t":"القردة والخنازير: عقوبة الاحتيال","e":"مسخ المعتدين في السبت قردة، وذكر القردة والخنازير.","ay":[[2,65,66],[5,60,60],[7,163,166]],"q":[{"bk":"saadi","s":2,"ay":65,"x":"فأوجب لهم هذا الذنب العظيم أن غضب الله عليهم، وجعلهم {قردة خاسئين}؛ حقيرين ذليلين، وجعل الله هذه العقوبة: {66}{نكالاً لما بين يديها}؛ أي: لمن حضرها من الأمم، وبلغه خبرها ممن هو في وقتهم {وما خلفها}؛ أي: من بعدها فتقوم على العباد حجة الله، وليرتدعوا عن معاصيه، ولكنها لا تكون موعظة نافعة إلا للمتقين، وأما من عداهم فلا ينتفعون بالآيات.","w":"السعدي","en":"Al-Sa'di: this great sin brought Allah's anger on them and made them 'apes, despised', abased; He made this punishment a deterrent for those present and those after, so that Allah's proof stands over people and they hold back from disobedience, but it is a useful admonition only for the God-fearing, while others do not benefit from the signs."},{"bk":"ibnkathir","s":2,"ay":65,"x":"فَلَمَّا فَعَلُوا ذَلِكَ مَسَخَهُمُ اللَّهُ إِلَى صُورَةِ الْقِرَدَةِ، وَهِيَ أَشْبَهُ شَيْءٍ بِالْأَنَاسِيِّ فِي الشَّكْلِ الظَّاهِرِ وَلَيْسَتْ بِإِنْسَانٍ حَقِيقَةً. فَكَذَلِكَ أَعْمَالُ هَؤُلَاءِ وَحِيَلُهُمْ لَمَّا كَانَتْ مُشَابِهَةً لِلْحَقِّ فِي الظَّاهِرِ وَمُخَالِفَةً لَهُ فِي الْبَاطِنِ، كَانَ جَزَاؤُهُمْ مِنْ جِنْسِ عَمَلِهِمْ.","w":"ابن كثير","en":"Ibn Kathir: when they did that Allah transformed them into the form of apes, the creature most like humans in outward form though not a human; so their deeds and ruses resembled the truth outwardly and opposed it inwardly, so their recompense was of the kind of their deed."}]},{"id":"jamal","ch":"amthal","t":"الجمل في سمّ الخياط","e":"تعليق دخول المكذبين الجنة بدخول الجمل في سمّ الخياط.","ay":[[7,40,40]],"q":[{"bk":"saadi","s":7,"ay":40,"x":"وقوله عن أهل النار:{ولا يدخُلونَ الجنَّة حتى يلجَ الجملُ}: وهو البعير المعروف {في سَمِّ الخِياطِ}؛ أي: حتى يدخُلَ البعير الذي هو من أكبر الحيوانات جسماً في خرق الإبرة الذي هو من أضيق الأشياء. وهذا من باب تعليق الشيء بالمحال؛ أي: فكما أنه محالٌ دخول الجمل في سَمِّ الخياطِ؛ فكذلك المكذِّبون بآيات الله محالٌ دخولهم الجنة؛ قال تعالى:{إنَّه من يُشۡرِكۡ بالله فقد حرَّم اللهُ عليه الجنةَ ومأواه النارُ}؛ وقال هنا:{وكذلك نَجۡزي المجرمينَ}؛ أي: الذين كَثُرَ إجرامُهم، واشتدَّ طغيانُهم.","w":"السعدي","en":"Al-Sa'di: of the people of the Fire, 'they will not enter Paradise until the camel enters the eye of the needle': that is, until the camel, among the largest of animals, enters the needle's hole, among the narrowest of things; this ties it to the impossible, so as it is impossible for a camel to pass through a needle's eye, so it is impossible for those who deny Allah's signs to enter Paradise."},{"bk":"ibnkathir","s":7,"ay":40,"x":"ثُمَّ قَرَأَ رَسُولُ اللَّهِ ﷺ: ﴿لَا تُفَتَّحُ لَهُمْ أَبْوَابُ السَّمَاءِ [وَلا يَدْخُلُونَ الْجَنَّةَ حَتَّى يَلِجَ الْجَمَلُ فِي سَمِّ الْخِيَاطِ] ﴾ الْآيَةَ.","w":"ابن كثير","en":"Ibn Kathir: then the Messenger of Allah recited, 'the gates of heaven will not be opened for them, nor will they enter Paradise until the camel passes through the eye of the needle'."}]},{"id":"nahl","ch":"nima","t":"النحل: وحي الإلهام وشفاء الناس","e":"وحي الله إلى النحل وما يخرج من بطونها من شراب.","ay":[[16,68,69]],"q":[{"bk":"saadi","s":16,"ay":68,"x":"في خلق هذه النَّحلة الصغيرة، التي هداها الله هذه الهداية العجيبة، ويَسَّر لها المراعي، ثم الرجوع إلى بيوتها التي أصلحتها بتعليم الله لها وهدايته لها، ثم يخرج من بطونها هذا العسل اللذيذ مختلف الألوان بحسب اختلاف أرضها ومراعيها؛ فيه شفاء للناس من أمراض عديدة؛ فهذا دليلٌ على كمال عناية الله تعالى وتمام لطفه بعباده، وأنَّه الذي لا ينبغي أن يُحَبَّ غيره، ويُدْعى سواه.","w":"السعدي","en":"Al-Sa'di: in creating this small bee, which Allah guided in a wondrous way and made grazing easy for, then returning to the houses it prepared by Allah's teaching, then this delicious honey of varied colours comes from its belly, a healing for people from many illnesses; this is a proof of Allah's perfect care and gentleness with His servants and that no one else should be loved or called upon."},{"bk":"ibnkathir","s":16,"ay":68,"x":"الْمُرَادُ بِالْوَحْيِ هَاهُنَا: الْإِلْهَامُ وَالْهِدَايَةُ وَالْإِرْشَادُ إِلَى النَّحْلِ أَنْ تَتَّخِذَ مِنَ الْجِبَالِ بُيُوتًا تَأْوِي إِلَيْهَا، وَمِنَ الشَّجَرِ، وَمِمَّا يَعْرِشُونَ. ثُمَّ هِيَ مُحْكَمَةٌ فِي غَايَةِ الْإِتْقَانِ فِي تَسْدِيسِهَا وَرَصِّهَا، بِحَيْثُ لَا يَكُونُ بَيْنَهَا خلَل.","w":"ابن كثير","en":"Ibn Kathir: the inspiration here is the inspiration, guidance and direction to the bee to take houses in the mountains, the trees and what people build; then they are precisely and masterfully built in their hexagons and fitting, with no gap between them."}]},{"id":"anam","ch":"nima","t":"الأنعام: دفء ومنافع وجمال","e":"الأنعام: ما فيها من دفء ومنافع وجمال وركوب.","ay":[[16,5,8],[36,71,73],[23,21,22],[40,79,80]],"q":[{"bk":"saadi","s":16,"ay":5,"x":"{والأنعامَ خلقها لكم}؛ أي: لأجلكم ولأجل منافعكم ومصالحكم، من جملة منافعها العظيمة، أنَّ {لكم فيها دفءٌ}: مما تتَّخذون من أصوافها وأوبارها وأشعارها وجلودِها من الثياب والفرش والبيوت. {و} لكم فيها {منافعُ}: غيرُ ذلك، {ومنها تأكلون}. {6}{ولكُم فيها جمالٌ حين تُريحونَ وحين تَسۡرَحون}؛ أي: في وقت رواحها وراحتها وسكونها ووقت حركتها وسرحها، وذلك أنَّ جمالها لا يعود إليها منه شيءٌ؛ فإنَّكم أنتم الذين تتجمَّلون بها كما تتجملون بثيابكم وأولادكم وأموالكم وتُعْجَبون بذلك.","w":"السعدي","en":"Al-Sa'di: 'He created livestock for you', for your benefit; among their great benefits is warmth, from their wool, fur, hair and skins as clothes, bedding and tents, other benefits, and food from them. And there is beauty when you bring them home and when you drive them out, a beauty that returns nothing to them but is yours, as you adorn yourselves with them, as with clothes, children and wealth."},{"bk":"saadi","s":36,"ay":71,"x":"يأمُرُ تعالى العباد بالنظر إلى ما سَخَّر لهم من الأنعام وذلَّلها وجَعَلَهم مالكينَ لها مطاوعةً لهم في كلِّ أمرٍ يريدونَه منها، وأنَّه جعل لهم فيها منافعَ كثيرةً من حَمْلِهم وحَمْل أثقالِهِم ومحامِلِهم وأمْتِعَتِهم من محلٍّ إلى محلٍّ، ومن أكْلِهِم منها، وفيها دفءٌ، ومن أوبارِها وأصوافها وأشعارِها أثاثاً ومتاعاً إلى حينٍ، وفيها زينةٌ وجمالٌ وغيرُ ذلك من المنافع المشاهدة منها. {أفلا يشكرونَ} اللهَ تعالى الذي أنعم بهذه النعم، ويخلِصونَ له العبادةَ، ولا يتمتَّعون بها تمتُّعاً خالياً من العبرة والفكرة؟!","w":"السعدي","en":"Al-Sa'di: Allah bids people to look at the livestock He subdued and made them obedient owners of, with many benefits: carrying them and their loads and goods from place to place, food, warmth, wool, fur and hair as furnishings, adornment, and more; 'will they not give thanks?' to Allah and be sincere to Him, not enjoying these without reflection and consideration."}]},{"id":"ibil","ch":"nima","t":"الإبل: كيف خُلقت؟","e":"الأمر بالنظر إلى الإبل كيف خُلقت.","ay":[[88,17,20]],"q":[{"bk":"saadi","s":88,"ay":17,"x":"أي: ألا ينظُرون إلى خَلْقها البديع وكيف سخَّرها الله للعباد وذلَّلها لمنافعهم الكثيرة التي يضطَرُّون إليها؟ {وإلى الجبال كيف نُصِبَتۡ}: بهيئةٍ باهرةٍ حصل بها الاستقرار للأرض وثباتُها من الاضطراب وأودع [الله] فيها من المنافع الجليلة ما أودع، {وإلى الأرض كيف سُطِحَتۡ}؛ أي: مُدَّت مدًّا واسعاً، وسُهِّلت غاية التسهيل؛ ليستقرَّ العبادُ على ظهرها ويتمكَّنوا من حرثها وغراسها والبنيان فيها وسلوك طرقها. واعلم أنَّ تسطيحها لا ينافي أنَّها كرةٌ مستديرةٌ قد أحاطتِ الأفلاك فيها من جميع جوانبها كما دلَّ على ذلك النقل والعقل والحسُّ والمشاهدة؛ كما هو مذكورٌ معروفٌ عند كثيرٍ من الناس ، خصوصاً في هذه الأزمنة، التي وقف الناس على أكثر أرجائها بما أعطاهم الله من الأسباب المقرِّبة للبعيد؛ فإنَّ التسطيح إنَّما ينافي كرويَّة الجسم الصغير جدًّا، الذي لو سطح …","w":"السعدي","en":"Al-Sa'di: do they not look at its wondrous creation and how Allah subjected it to people and made it obedient for its many benefits they need? And at the mountains, how they are fixed, and at the earth, how it is spread out."},{"bk":"ibnkathir","s":88,"ay":17,"x":"يَقُولُ تَعَالَى آمِرًا عِبَادَهُ بِالنَّظَرِ فِي مَخْلُوقَاتِهِ الدَّالَّةِ عَلَى قُدْرَتِهِ وَعَظَمَتِهِ: ﴿أَفَلا يَنْظُرُونَ إِلَى الإبِلِ كَيْفَ خُلِقَتْ﴾ ؟ فَإِنَّهَا خَلق عَجِيبٌ، وَتَرْكِيبُهَا غَرِيبٌ، فَإِنَّهَا فِي غَايَةِ الْقُوَّةِ وَالشِّدَّةِ، وَهِيَ مَعَ ذَلِكَ تَلِينُ لِلْحَمْلِ الثَّقِيلِ، وَتَنْقَادُ لِلْقَائِدِ الضَّعِيفِ، وَتُؤْكَلُ، وَيُنْتَفَعُ بِوَبَرِهَا، وَيُشْرَبُ لَبَنُهَا.","w":"ابن كثير","en":"Ibn Kathir: Allah orders His servants to look at His creatures that show His power and greatness: 'Do they not look at the camel, how it was created?' It is a wondrous creation and strange in composition, of utmost strength and might yet yielding to heavy loads, led by a weak leader, eaten, its hair used and its milk drunk."}]},{"id":"adiyat","ch":"nima","t":"العاديات والخيل: الشكر والكنود","e":"إقسام الله بالعاديات ضبحاً، وتسخير الخيل والبغال والحمير.","ay":[[100,1,6],[16,8,8]],"q":[{"bk":"saadi","s":100,"ay":1,"x":"وهي مكية بِسْمِ اللَّهِ الرَّحْمَنِ الرَّحِيمِ {1} أقسم [الله تبارك و] تعالى بالخيل؛ لما فيها من آياتِه الباهرة ونعَمِه الظَّاهرة ما هو معلومٌ للخلق، وأقسم تعالى بها في الحال التي لا يشاركُها فيه غيرها من أنواع الحيوانات، فقال:{والعادياتِ ضَبۡحاً}؛ أي: العاديات عدواً بليغاً قويًّا يصدر عنه الضَّبحُ، وهو صوت نَفَسها في صدرها عند اشتداد عَدْوها. {2}{فالمورياتِ}: بحوافرهنَّ ما يطأنَ عليه من الأحجار، {قَدۡحاً}؛ أي: تنقدح النار من صلابة حوافرهنَّ وقوتهنَّ إذا عَدَوْنَ. {3}{فالمغيراتِ}: على الأعداء، {صبحاً}: وهذا أمرٌ أغلبيٌّ أنَّ الغارة تكون صباحاً.","w":"السعدي","en":"Al-Sa'di: Allah swore by the horses for the wonderful signs and clear blessings in them that people know, and swore by them in a state no other animals share: 'by the racers, panting', the sound of their breath in their chests as they run hard; 'striking sparks' from the hardness and strength of their hooves; 'raiding at dawn', raids usually being at dawn."},{"bk":"ibnkathir","s":100,"ay":1,"x":"قَالَ ابْنُ أَبِي حَاتِمٍ: حَدَّثَنَا أَبُو سَعِيدٍ الْأَشَجُّ، حَدَّثَنَا عَبْدَةُ، عَنِ الْأَعْمَشِ، عَنْ إِبْرَاهِيمَ، عَنْ عَبْدِ اللَّهِ: ﴿وَالْعَادِيَاتِ ضَبْحًا﴾ قَالَ: الْإِبِلُ. وَقَالَ عَلِيٌّ: هِيَ الْإِبِلُ.","w":"ابن كثير","en":"Ibn Kathir: Ibn Abi Hatim reported from Abd Allah (ibn Mas'ud) that 'by the racers, panting' means camels, and Ali said it means camels."}]},{"id":"tayrmusakh","ch":"nima","t":"الطير مسخّرات في جو السماء","e":"الطير مسخّرات في جو السماء ما يمسكهن إلا الله.","ay":[[16,79,79],[67,19,19],[24,41,41]],"q":[{"bk":"saadi","s":67,"ay":19,"x":"وهذا عتابٌ وحثٌّ على النظر إلى حالة الطير التي سخَّرها الله وسخَّر لها الجوَّ والهواء؛ تصفُّ فيه أجنحتها للطيران وتقبِضُها للوقوع، فتظلُّ سابحةً في الجوِّ متردِّدة فيه بحسب إرادتها وحاجتها، {ما يمسِكُهُنَّ إلاَّ الرحمنُ}: فإنَّه الذي سخَّر لهنَّ الجوَّ وجعل أجسادها وخلقتها في حالة مستعدةٍ للطيران؛ فمن نظر في حالة الطير واعتبر فيها؛ دلَّتْه على قدرة الباري وعنايته الربانيَّة، وأنَّه الواحدُ الأحدُ الذي لا تنبغي العبادة إلاَّ له. {إنَّه بكلِّ شيءٍ بصيرٌ}: فهو المدبِّر لعباده بما يليق بهم وتقتضيه حكمته.","w":"السعدي","en":"Al-Sa'di: this is a reproach and encouragement to look at the birds Allah subjected, with the air subjected to them, spreading their wings to fly and folding them to land, staying afloat in the air as they wish; 'none holds them but the Merciful'; whoever looks at the state of the birds and reflects is led to Allah's power and care and that He alone is worthy of worship."},{"bk":"ibnkathir","s":16,"ay":79,"x":"ثُمَّ نَبَّهَ تَعَالَى عِبَادَهُ إِلَى النَّظَرِ إِلَى الطَّيْرِ الْمُسَخَّرِ بَيْنَ السَّمَاءِ وَالْأَرْضِ، كَيْفَ جَعَلَهُ يَطِيرُ بِجَنَاحَيْهِ بَيْنَ السَّمَاءِ وَالْأَرْضِ، فِي جَوِّ السَّمَاءِ مَا يُمْسِكُهُ هُنَاكَ إِلَّا اللَّهُ بِقُدْرَتِهِ تَعَالَى، الَّذِي جَعَلَ فِيهَا قُوًى تَفْعَلُ ذَلِكَ، وَسَخَّرَ الْهَوَاءَ يَحْمِلُهَا وَيَسَّرَ الطَّيْرَ لِذَلِكَ، كَمَا قَالَ تَعَالَى فِي سُورَةِ الْمُلْكِ: ﴿أَوَلَمْ يَرَوْا إِلَى الطَّيْرِ فَوْقَهُمْ صَافَّاتٍ وَيَقْبِضْنَ مَا يُمْسِكُهُنَّ إِلا الرَّحْمَنُ إِنَّهُ بِكُلِّ شَيْءٍ بَصِيرٌ﴾ [الْمُلْكِ: ١٩] . وَقَالَ هَاهُنَا: ﴿إِنَّ فِي ذَلِكَ لآيَاتٍ لِقَوْمٍ يُؤْمِنُونَ﴾","w":"ابن كثير","en":"Ibn Kathir: Allah then drew people's attention to the birds subjected between sky and earth, flying with their wings in the sky, which nothing holds there but Allah by His power, who put in them forces that do that and made the air carry them, as He said in Surat al-Mulk 'Have they not seen the birds above them spreading and folding their wings? None holds them but the Most Merciful.'"}]},{"id":"umam","ch":"umam","t":"«أمم أمثالكم»: كل دابة وطائر","e":"كل دابة وطائر أمة من الأمم.","ay":[[6,38,38]],"q":[{"bk":"ibnkathir","s":6,"ay":38,"x":"وَقَوْلُهُ: ﴿وَمَا مِنْ دَابَّةٍ فِي الأرْضِ وَلا طَائِرٍ يَطِيرُ بِجَنَاحَيْهِ إِلا أُمَمٌ أَمْثَالُكُمْ﴾ قَالَ مُجَاهِدٌ: أَيْ أَصْنَافٌ مُصَنَّفة تُعرَف بِأَسْمَائِهَا. وَقَالَ قَتَادَةُ: الطَّيْرُ أُمَّةٌ، وَالْإِنْسُ أُمَّةٌ، وَالْجِنُّ أُمَّةٌ.","w":"ابن كثير","en":"Ibn Kathir: Mujahid said 'communities like you' means classes that are known by their names, and Qatada said the birds are a community, humans a community and jinn a community."},{"bk":"qurtubi","s":6,"ay":38,"x":"(إِلَّا أُمَمٌ أَمْثالُكُمْ) أَيْ هُمْ جَمَاعَاتٌ مِثْلُكُمْ فِي أَنَّ اللَّهَ عَزَّ وَجَلَّ خَلَقَهُمْ، وَتَكَفَّلَ بأرزاقهم، وعدل عليهم، فلا ينبغي أَنْ تَظْلِمُوهُمْ، وَلَا تُجَاوِزُوا فِيهِمْ مَا أُمِرْتُمْ بِهِ. وَ (دَابَّةٌ) تَقَعُ عَلَى جَمِيعِ مَا دَبَّ، وَخَصَّ بِالذِّكْرِ مَا فِي الْأَرْضِ دُونَ السَّمَاءِ لِأَنَّهُ الَّذِي يَعْرِفُونَهُ وَيُعَايِنُونَهُ.","w":"القرطبي","en":"Al-Qurtubi: 'communities like you' means groups like you in that Allah created them, undertook their provision and was just to them, so it is not right to wrong them or exceed in their regard what you were commanded; 'beast' covers everything that creeps, and the earth is singled out because it is what they know and see."}]},{"id":"tasbih","ch":"umam","t":"تسبيح الطير والدواب وسجود المخلوقات","e":"تسبيح من في السماوات والأرض والطير صافات.","ay":[[24,41,41],[17,44,44],[22,18,18]],"q":[{"bk":"saadi","s":24,"ay":41,"x":"نبَّه تعالى عبادَه على عظمتِهِ وكمال سلطانِهِ وافتقارِ جميع المخلوقاتِ له في ربوبيَّتها وعبادتها، فقال:{ألم تر أنَّ الله يسبِّحُ له مَن في السمواتِ والأرضِ}: من حيوان وجمادٍ، {والطيرُ صافاتٍ}؛ أي: صافات أجنِحَتِها في جوِّ السماء تسبِّحُ ربَّها. {كلٌّ}: من هذه المخلوقات {قد عَلِمَ صلاتَه وتسبيحَه}؛ أي: كلٌّ له صلاةٌ وعبادةٌ بحسب حاله اللائقة به، وقد ألهمه الله تلك الصلاة والتسبيح: إما بواسطة الرسل كالجن والإنس والملائكة، وإما بإلهام منه تعالى كسائر المخلوقات غير ذلك.","w":"السعدي","en":"Al-Sa'di: Allah reminds His servants of His greatness and perfect authority and the need of all creatures for Him in their lordship and worship: 'all in the heavens and the earth glorify Him', animal and inanimate, 'and the birds with wings spread'; each one knows its prayer and glorification, each according to its state, Allah having inspired it, either through messengers as with jinn, humans and angels, or by inspiration from Him for other creatures."},{"bk":"ibnkathir","s":24,"ay":41,"x":"وَقَوْلُهُ: ﴿وَالطَّيْرُ صَافَّاتٍ﴾ أَيْ: فِي حَالِ طَيَرَانِهَا تُسَبِّحُ رَبَّهَا وَتَعْبُدُهُ بِتَسْبِيحٍ أَلْهَمَهَا وَأَرْشَدَهَا إِلَيْهِ، وَهُوَ يَعْلَمُ مَا هِيَ فَاعِلَةٌ؛ وَلِهَذَا قَالَ: ﴿كُلٌّ قَدْ عَلِمَ صَلاتَهُ وَتَسْبِيحَهُ﴾ أَيْ: كُلٌّ قَدْ أَرْشَدَهُ إِلَى طَرِيقَتِهِ وَمَسْلَكِهِ فِي عِبَادَةِ اللَّهِ، عَزَّ وَجَلَّ. ثُمَّ أَخْبَرَ أَنَّهُ عَالِمٌ بِجَمِيعِ ذَلِكَ، لَا يَخْفَى عَلَيْهِ مِنْ ذَلِكَ شَيْءٌ؛ وَلِهَذَا قَالَ: ﴿وَاللَّهُ عَلِيمٌ بِمَا يَفْعَلُونَ﴾ .","w":"ابن كثير","en":"Ibn Kathir: the birds in flight glorify their Lord and worship Him with a glorification He inspired them with, and He knows what they do; 'each knows its prayer and glorification' means each is guided to its way of worshipping Allah; then He told that He knows all of it, nothing hidden from Him."}]},{"id":"rizq","ch":"umam","t":"الدواب والرزق على الله","e":"تكفّل الله برزق الدواب وخلقها من ماء.","ay":[[11,6,6],[29,60,60],[24,45,45]],"q":[{"bk":"saadi","s":29,"ay":60,"x":"أي: الباري تبارك وتعالى قد تكفَّل بأرزاق الخلائق كلِّهم قويِّهم وعاجزهم؛ فكم {من دابَّةٍ} في الأرض ضعيفةِ القُوى ضعيفة العقل، {لا تَحۡمِلُ رزقَها}: ولا تدَّخِرُه، بل لم تزلْ لا شيء معها من الرزق، ولا يزال الله يسخِّرُ لها الرزقَ في كل وقت بوقته. {اللَّهُ يرزُقُها وإيَّاكم}: فكلكم عيالُ الله القائم برزقكم كما قام بِخَلْقِكُم وتدبيرِكم.","w":"السعدي","en":"Al-Sa'di: the Creator has undertaken the provision of all creatures, strong and weak; how many beasts on earth, weak in strength and mind, 'do not carry their provision' and do not store it, never having anything, yet Allah keeps subjecting provision to them at its time; 'Allah provides for them and for you'; you are all Allah's dependants, He providing for you as He created and managed you."},{"bk":"saadi","s":24,"ay":45,"x":"ينبِّه عباده على ما يشاهدونَه أنَّه خَلَقَ جميع الدوابِّ التي على وجه الأرض {من ماءٍ}؛ أي: مادَّتُها كلُّها الماء؛ كما قال تعالى:{وَجَعَلۡنا من الماءِ كلَّ شيءٍ حيٍّ}؛ فالحيوانات التي تتوالد، مادتها ماءُ النطفةِ حين يلقحُ الذَّكر الأنثى، والحيوانات التي تتولَّد من الأرض لا تتولَّد إلاَّ من الرطوبات المائيَّة؛ كالحشرات، لا يوجد منها شيءٌ يتولَّد من غير ماء أبداً؛ فالمادَّة واحدةٌ، ولكن الخِلْقَةَ مختلفةٌ من وجوه كثيرة. {فمنهم من يمشي على بطنِهِ}؛ كالحيَّة ونحوها، {ومنهم مَنۡ يمشي على رجلينِ}؛ كالآدميِّين وكثيرٍ من الطُّيور، {ومنهم من يمشي على أربع}؛ كبهيمة الأنعام ونحوها؛ فاختلافُها مع أنَّ الأصل واحدٌ يدلُّ على نفوذِ مشيئة الله وعموم قدرتِهِ.","w":"السعدي","en":"Al-Sa'di: Allah draws attention to what they see: He created all beasts on earth 'from water', their matter all water, as in 'We made from water every living thing'; those that reproduce come from the water of the sperm, and those that arise from the earth do so from watery moistures, like insects; the matter is one."},{"bk":"ibnkathir","s":24,"ay":45,"x":"يَذْكُرُ تَعَالَى قُدْرَتَهُ التَّامَّةَ وَسُلْطَانَهُ الْعَظِيمَ، فِي خَلْقِهِ أَنْوَاعَ [الْمَخْلُوقَاتِ] . عَلَى اخْتِلَافِ أَشْكَالِهَا وَأَلْوَانِهَا، وَحَرَكَاتِهَا وَسُكَنَاتِهَا، مِنْ مَاءٍ وَاحِدٍ، ﴿فَمِنْهُمْ مَنْ يَمْشِي عَلَى بَطْنِهِ﴾ كَالْحَيَّةِ وَمَا شَاكَلَهَا، ﴿وَمِنْهُمْ مَنْ يَمْشِي عَلَى رِجْلَيْنِ﴾ كَالْإِنْسَانِ وَالطَّيْرِ، ﴿وَمِنْهُمْ مَنْ يَمْشِي عَلَى أَرْبَعٍ﴾ كَالْأَنْعَامِ وَسَائِرِ الْحَيَوَانَاتِ؛ وَلِهَذَا قَالَ: ﴿يَخْلُقُ اللَّهُ مَا يَشَاءُ﴾ أَيْ: بِقُدْرَتِهِ؛ لِأَنَّهُ مَا شَاءَ كَانَ، وَمَا لَمْ يَشَأْ لَمْ يَكُنْ؛ وَلِهَذَا قَالَ: ﴿إِنَّ اللَّهَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ﴾ .","w":"ابن كثير","en":"Ibn Kathir: Allah mentions His complete power and great authority in creating many kinds of creatures, of differing shapes, colours, movements and stillness, from one water: some walk on their bellies like the snake, some on two legs like humans and birds."}]},{"id":"shar","ch":"umam","t":"شر الدواب عند الله","e":"وصف من لم ينتفع بالآيات بأنه شر الدواب عند الله.","ay":[[8,22,22],[8,55,55]],"q":[{"bk":"saadi","s":8,"ay":22,"x":"يقول تعالى: {إنَّ شرَّ الدوابِّ عند الله}: مَنْ لم تُفِذْ فيهم الآيات والنذر، وهم {الصُّمُّ}: عن استماع الحق، {البكم}: عن النطق به، {الذين لا يعقلونَ}: ما ينفعهم ويؤثرونَه على ما يضرُّهم؛ فهؤلاء شرٌّ عند الله من شرار الدواب ؛ لأنَّ الله أعطاهم أسماعاً وأبصاراً وأفئدة ليستعملوها في طاعة الله، فاستعملوها في معاصيه، وعدموا بذلك الخير الكثير؛ فإنَّهم كانوا بصدد أن يكونوا من خيار البريَّة، فأبوا هذا الطريق، واختاروا لأنفسهم أن يكونوا من شرِّ البريَّة. والسمعُ الذين نفاه الله عنهم سمعُ المعنى المؤثِّر في القلب، وأما سمعُ الحجَّة؛ فقد قامت حجَّة الله تعالى عليهم بما سمعوه من آياته.","w":"السعدي","en":"Al-Sa'di: the worst of creatures in Allah's sight are those on whom signs and warnings had no effect: deaf to hearing the truth, dumb to speaking it, who do not understand what benefits them; they are worse than the worst beasts because Allah gave them hearing, sight and hearts to use in obeying Him, and they used them in disobedience, losing much good when they could have been among the best of creation."},{"bk":"ibnkathir","s":8,"ay":22,"x":"ثُمَّ أَخْبَرَ تَعَالَى أَنَّ هَذَا الضَّرْبَ مِنْ بَنِي آدَمَ شَرُّ الْخَلْقِ وَالْخَلِيقَةِ، فَقَالَ: ﴿إِنَّ شَرَّ الدَّوَابِّ عِنْدَ اللَّهِ الصُّمُّ﴾ أَيْ: عَنْ سَمَاعِ الْحَقِّ ﴿الْبُكْمُ﴾ عَنْ فَهْمِهِ؛ وَلِهَذَا قَالَ: ﴿الَّذِينَ لَا يَعْقِلُونَ﴾ فَهَؤُلَاءِ شَرُّ الْبَرِيَّةِ؛ لِأَنَّ كُلَّ دَابَّةٍ مِمَّا سِوَاهُمْ مُطِيعَةٌ لِلَّهِ [عَزَّ وَجَلَّ] فِيمَا خَلَقَهَا لَهُ، وَهَؤُلَاءِ خُلِقُوا لِلْعِبَادَةِ فَكَفَرُوا؛ وَلِهَذَا شَبَّهَهُمْ بِالْأَنْعَامِ فِي قَوْلِهِ: ﴿وَمَثَلُ الَّذِينَ كَفَرُوا كَمَثَلِ الَّذِي يَنْعِقُ بِمَا لَا يَسْمَعُ إِلا دُعَاءً وَنِدَاءً [صُمٌّ بُكْمٌ عُمْيٌ فَهُمْ لَا يَعْقِلُونَ] ﴾ [الْبَقَرَةِ: ١٧١] . وَقَالَ فِي الْآيَةِ الْأُخْرَى: ﴿أُولَئِكَ كَالأنْعَامِ بَلْ هُمْ أَضَلُّ أُولَئِكَ هُمُ الْغَافِلُونَ﴾ [الْأَعْرَافِ: ١٧٩] .","w":"ابن كثير","en":"Ibn Kathir: Allah then says that this kind of humans is the worst of creation, for every other beast is obedient to Allah in what it was created for, while these were created for worship and disbelieved; so He likened them to cattle, 'they are like cattle, rather more astray'."}]}],"ay":{"32":"۞ إِنَّ ٱللَّهَ لَا يَسۡتَحۡيِۦٓ أَن يَضۡرِبَ مَثَلٗا مَّا بَعُوضَةٗ فَمَا فَوۡقَهَاۚ فَأَمَّا ٱلَّذِينَ ءَامَنُواْ فَيَعۡلَمُونَ أَنَّهُ ٱلۡحَقُّ مِن رَّبِّهِمۡۖ وَأَمَّا ٱلَّذِينَ كَفَرُواْ فَيَقُولُونَ مَاذَآ أَرَادَ ٱللَّهُ بِهَٰذَا مَثَلٗاۘ يُضِلُّ بِهِۦ كَثِيرٗا وَيَهۡدِي بِهِۦ كَثِيرٗاۚ وَمَا يُضِلُّ بِهِۦٓ إِلَّا ٱلۡفَٰسِقِينَ","71":"وَلَقَدۡ عَلِمۡتُمُ ٱلَّذِينَ ٱعۡتَدَوۡاْ مِنكُمۡ فِي ٱلسَّبۡتِ فَقُلۡنَا لَهُمۡ كُونُواْ قِرَدَةً خَٰسِـِٔينَ","72":"فَجَعَلۡنَٰهَا نَكَٰلٗا لِّمَا بَيۡنَ يَدَيۡهَا وَمَا خَلۡفَهَا وَمَوۡعِظَةٗ لِّلۡمُتَّقِينَ","73":"وَإِذۡ قَالَ مُوسَىٰ لِقَوۡمِهِۦٓ إِنَّ ٱللَّهَ يَأۡمُرُكُمۡ أَن تَذۡبَحُواْ بَقَرَةٗۖ قَالُوٓاْ أَتَتَّخِذُنَا هُزُوٗاۖ قَالَ أَعُوذُ بِٱللَّهِ أَنۡ أَكُونَ مِنَ ٱلۡجَٰهِلِينَ","74":"قَالُواْ ٱدۡعُ لَنَا رَبَّكَ يُبَيِّن لَّنَا مَا هِيَۚ قَالَ إِنَّهُۥ يَقُولُ إِنَّهَا بَقَرَةٞ لَّا فَارِضٞ وَلَا بِكۡرٌ عَوَانُۢ بَيۡنَ ذَٰلِكَۖ فَٱفۡعَلُواْ مَا تُؤۡمَرُونَ","75":"قَالُواْ ٱدۡعُ لَنَا رَبَّكَ يُبَيِّن لَّنَا مَا لَوۡنُهَاۚ قَالَ إِنَّهُۥ يَقُولُ إِنَّهَا بَقَرَةٞ صَفۡرَآءُ فَاقِعٞ لَّوۡنُهَا تَسُرُّ ٱلنَّٰظِرِينَ","76":"قَالُواْ ٱدۡعُ لَنَا رَبَّكَ يُبَيِّن لَّنَا مَا هِيَ إِنَّ ٱلۡبَقَرَ تَشَٰبَهَ عَلَيۡنَا وَإِنَّآ إِن شَآءَ ٱللَّهُ لَمُهۡتَدُونَ","77":"قَالَ إِنَّهُۥ يَقُولُ إِنَّهَا بَقَرَةٞ لَّا ذَلُولٞ تُثِيرُ ٱلۡأَرۡضَ وَلَا تَسۡقِي ٱلۡحَرۡثَ مُسَلَّمَةٞ لَّا شِيَةَ فِيهَاۚ قَالُواْ ٱلۡـَٰٔنَ جِئۡتَ بِٱلۡحَقِّۚ فَذَبَحُوهَا وَمَا كَادُواْ يَفۡعَلُونَ","78":"وَإِذۡ قَتَلۡتُمۡ نَفۡسٗا فَٱدَّٰرَٰءۡتُمۡ فِيهَاۖ وَٱللَّهُ مُخۡرِجٞ مَّا كُنتُمۡ تَكۡتُمُونَ","79":"فَقُلۡنَا ٱضۡرِبُوهُ بِبَعۡضِهَاۚ كَذَٰلِكَ يُحۡيِ ٱللَّهُ ٱلۡمَوۡتَىٰ وَيُرِيكُمۡ ءَايَٰتِهِۦ لَعَلَّكُمۡ تَعۡقِلُونَ","265":"أَوۡ كَٱلَّذِي مَرَّ عَلَىٰ قَرۡيَةٖ وَهِيَ خَاوِيَةٌ عَلَىٰ عُرُوشِهَا قَالَ أَنَّىٰ يُحۡيِۦ هَٰذِهِ ٱللَّهُ بَعۡدَ مَوۡتِهَاۖ فَأَمَاتَهُ ٱللَّهُ مِاْئَةَ عَامٖ ثُمَّ بَعَثَهُۥۖ قَالَ كَمۡ لَبِثۡتَۖ قَالَ لَبِثۡتُ يَوۡمًا أَوۡ بَعۡضَ يَوۡمٖۖ قَالَ بَل لَّبِثۡتَ مِاْئَةَ عَامٖ فَٱنظُرۡ إِلَىٰ طَعَامِكَ وَشَرَابِكَ لَمۡ يَتَسَنَّهۡۖ وَٱنظُرۡ إِلَىٰ حِمَارِكَ وَلِنَجۡعَلَكَ ءَايَةٗ لِّلنَّاسِۖ وَٱنظُرۡ إِلَى ٱلۡعِظَامِ كَيۡفَ نُنشِزُهَا ثُمَّ نَكۡسُوهَا لَحۡمٗاۚ فَلَمَّا تَبَيَّنَ لَهُۥ قَالَ أَعۡلَمُ أَنَّ ٱللَّهَ عَلَىٰ كُلِّ شَيۡءٖ قَدِيرٞ","266":"وَإِذۡ قَالَ إِبۡرَٰهِـۧمُ رَبِّ أَرِنِي كَيۡفَ تُحۡيِ ٱلۡمَوۡتَىٰۖ قَالَ أَوَلَمۡ تُؤۡمِنۖ قَالَ بَلَىٰ وَلَٰكِن لِّيَطۡمَئِنَّ قَلۡبِيۖ قَالَ فَخُذۡ أَرۡبَعَةٗ مِّنَ ٱلطَّيۡرِ فَصُرۡهُنَّ إِلَيۡكَ ثُمَّ ٱجۡعَلۡ عَلَىٰ كُلِّ جَبَلٖ مِّنۡهُنَّ جُزۡءٗا ثُمَّ ٱدۡعُهُنَّ يَأۡتِينَكَ سَعۡيٗاۚ وَٱعۡلَمۡ أَنَّ ٱللَّهَ عَزِيزٌ حَكِيمٞ","341":"وَرَسُولًا إِلَىٰ بَنِيٓ إِسۡرَٰٓءِيلَ أَنِّي قَدۡ جِئۡتُكُم بِـَٔايَةٖ مِّن رَّبِّكُمۡ أَنِّيٓ أَخۡلُقُ لَكُم مِّنَ ٱلطِّينِ كَهَيۡـَٔةِ ٱلطَّيۡرِ فَأَنفُخُ فِيهِ فَيَكُونُ طَيۡرَۢا بِإِذۡنِ ٱللَّهِۖ وَأُبۡرِئُ ٱلۡأَكۡمَهَ وَٱلۡأَبۡرَصَ وَأُحۡيِ ٱلۡمَوۡتَىٰ بِإِذۡنِ ٱللَّهِۖ وَأُنَبِّئُكُم بِمَا تَأۡكُلُونَ وَمَا تَدَّخِرُونَ فِي بُيُوتِكُمۡۚ إِنَّ فِي ذَٰلِكَ لَأٓيَةٗ لَّكُمۡ إِن كُنتُم مُّؤۡمِنِينَ","695":"۞ وَٱتۡلُ عَلَيۡهِمۡ نَبَأَ ٱبۡنَيۡ ءَادَمَ بِٱلۡحَقِّ إِذۡ قَرَّبَا قُرۡبَانٗا فَتُقُبِّلَ مِنۡ أَحَدِهِمَا وَلَمۡ يُتَقَبَّلۡ مِنَ ٱلۡأٓخَرِ قَالَ لَأَقۡتُلَنَّكَۖ قَالَ إِنَّمَا يَتَقَبَّلُ ٱللَّهُ مِنَ ٱلۡمُتَّقِينَ","696":"لَئِنۢ بَسَطتَ إِلَيَّ يَدَكَ لِتَقۡتُلَنِي مَآ أَنَا۠ بِبَاسِطٖ يَدِيَ إِلَيۡكَ لِأَقۡتُلَكَۖ إِنِّيٓ أَخَافُ ٱللَّهَ رَبَّ ٱلۡعَٰلَمِينَ","697":"إِنِّيٓ أُرِيدُ أَن تَبُوٓأَ بِإِثۡمِي وَإِثۡمِكَ فَتَكُونَ مِنۡ أَصۡحَٰبِ ٱلنَّارِۚ وَذَٰلِكَ جَزَٰٓؤُاْ ٱلظَّٰلِمِينَ","698":"فَطَوَّعَتۡ لَهُۥ نَفۡسُهُۥ قَتۡلَ أَخِيهِ فَقَتَلَهُۥ فَأَصۡبَحَ مِنَ ٱلۡخَٰسِرِينَ","699":"فَبَعَثَ ٱللَّهُ غُرَابٗا يَبۡحَثُ فِي ٱلۡأَرۡضِ لِيُرِيَهُۥ كَيۡفَ يُوَٰرِي سَوۡءَةَ أَخِيهِۚ قَالَ يَٰوَيۡلَتَىٰٓ أَعَجَزۡتُ أَنۡ أَكُونَ مِثۡلَ هَٰذَا ٱلۡغُرَابِ فَأُوَٰرِيَ سَوۡءَةَ أَخِيۖ فَأَصۡبَحَ مِنَ ٱلنَّٰدِمِينَ","728":"قُلۡ هَلۡ أُنَبِّئُكُم بِشَرّٖ مِّن ذَٰلِكَ مَثُوبَةً عِندَ ٱللَّهِۚ مَن لَّعَنَهُ ٱللَّهُ وَغَضِبَ عَلَيۡهِ وَجَعَلَ مِنۡهُمُ ٱلۡقِرَدَةَ وَٱلۡخَنَازِيرَ وَعَبَدَ ٱلطَّٰغُوتَۚ أُوْلَٰٓئِكَ شَرّٞ مَّكَانٗا وَأَضَلُّ عَن سَوَآءِ ٱلسَّبِيلِ","778":"إِذۡ قَالَ ٱللَّهُ يَٰعِيسَى ٱبۡنَ مَرۡيَمَ ٱذۡكُرۡ نِعۡمَتِي عَلَيۡكَ وَعَلَىٰ وَٰلِدَتِكَ إِذۡ أَيَّدتُّكَ بِرُوحِ ٱلۡقُدُسِ تُكَلِّمُ ٱلنَّاسَ فِي ٱلۡمَهۡدِ وَكَهۡلٗاۖ وَإِذۡ عَلَّمۡتُكَ ٱلۡكِتَٰبَ وَٱلۡحِكۡمَةَ وَٱلتَّوۡرَىٰةَ وَٱلۡإِنجِيلَۖ وَإِذۡ تَخۡلُقُ مِنَ ٱلطِّينِ كَهَيۡـَٔةِ ٱلطَّيۡرِ بِإِذۡنِي فَتَنفُخُ فِيهَا فَتَكُونُ طَيۡرَۢا بِإِذۡنِيۖ وَتُبۡرِئُ ٱلۡأَكۡمَهَ وَٱلۡأَبۡرَصَ بِإِذۡنِيۖ وَإِذۡ تُخۡرِجُ ٱلۡمَوۡتَىٰ بِإِذۡنِيۖ وَإِذۡ كَفَفۡتُ بَنِيٓ إِسۡرَٰٓءِيلَ عَنكَ إِذۡ جِئۡتَهُم بِٱلۡبَيِّنَٰتِ فَقَالَ ٱلَّذِينَ كَفَرُواْ مِنۡهُمۡ إِنۡ هَٰذَآ إِلَّا سِحۡرٞ مُّبِينٞ","826":"وَمَا مِن دَآبَّةٖ فِي ٱلۡأَرۡضِ وَلَا طَٰٓئِرٖ يَطِيرُ بِجَنَاحَيۡهِ إِلَّآ أُمَمٌ أَمۡثَالُكُمۚ مَّا فَرَّطۡنَا فِي ٱلۡكِتَٰبِ مِن شَيۡءٖۚ ثُمَّ إِلَىٰ رَبِّهِمۡ يُحۡشَرُونَ","993":"إِنَّ ٱلَّذِينَ كَذَّبُواْ بِـَٔايَٰتِنَا وَٱسۡتَكۡبَرُواْ عَنۡهَا لَا تُفَتَّحُ لَهُمۡ أَبۡوَٰبُ ٱلسَّمَآءِ وَلَا يَدۡخُلُونَ ٱلۡجَنَّةَ حَتَّىٰ يَلِجَ ٱلۡجَمَلُ فِي سَمِّ ٱلۡخِيَاطِۚ وَكَذَٰلِكَ نَجۡزِي ٱلۡمُجۡرِمِينَ","1026":"وَإِلَىٰ ثَمُودَ أَخَاهُمۡ صَٰلِحٗاۚ قَالَ يَٰقَوۡمِ ٱعۡبُدُواْ ٱللَّهَ مَا لَكُم مِّنۡ إِلَٰهٍ غَيۡرُهُۥۖ قَدۡ جَآءَتۡكُم بَيِّنَةٞ مِّن رَّبِّكُمۡۖ هَٰذِهِۦ نَاقَةُ ٱللَّهِ لَكُمۡ ءَايَةٗۖ فَذَرُوهَا تَأۡكُلۡ فِيٓ أَرۡضِ ٱللَّهِۖ وَلَا تَمَسُّوهَا بِسُوٓءٖ فَيَأۡخُذَكُمۡ عَذَابٌ أَلِيمٞ","1027":"وَٱذۡكُرُوٓاْ إِذۡ جَعَلَكُمۡ خُلَفَآءَ مِنۢ بَعۡدِ عَادٖ وَبَوَّأَكُمۡ فِي ٱلۡأَرۡضِ تَتَّخِذُونَ مِن سُهُولِهَا قُصُورٗا وَتَنۡحِتُونَ ٱلۡجِبَالَ بُيُوتٗاۖ فَٱذۡكُرُوٓاْ ءَالَآءَ ٱللَّهِ وَلَا تَعۡثَوۡاْ فِي ٱلۡأَرۡضِ مُفۡسِدِينَ","1028":"قَالَ ٱلۡمَلَأُ ٱلَّذِينَ ٱسۡتَكۡبَرُواْ مِن قَوۡمِهِۦ لِلَّذِينَ ٱسۡتُضۡعِفُواْ لِمَنۡ ءَامَنَ مِنۡهُمۡ أَتَعۡلَمُونَ أَنَّ صَٰلِحٗا مُّرۡسَلٞ مِّن رَّبِّهِۦۚ قَالُوٓاْ إِنَّا بِمَآ أُرۡسِلَ بِهِۦ مُؤۡمِنُونَ","1029":"قَالَ ٱلَّذِينَ ٱسۡتَكۡبَرُوٓاْ إِنَّا بِٱلَّذِيٓ ءَامَنتُم بِهِۦ كَٰفِرُونَ","1030":"فَعَقَرُواْ ٱلنَّاقَةَ وَعَتَوۡاْ عَنۡ أَمۡرِ رَبِّهِمۡ وَقَالُواْ يَٰصَٰلِحُ ٱئۡتِنَا بِمَا تَعِدُنَآ إِن كُنتَ مِنَ ٱلۡمُرۡسَلِينَ","1031":"فَأَخَذَتۡهُمُ ٱلرَّجۡفَةُ فَأَصۡبَحُواْ فِي دَارِهِمۡ جَٰثِمِينَ","1032":"فَتَوَلَّىٰ عَنۡهُمۡ وَقَالَ يَٰقَوۡمِ لَقَدۡ أَبۡلَغۡتُكُمۡ رِسَالَةَ رَبِّي وَنَصَحۡتُ لَكُمۡ وَلَٰكِن لَّا تُحِبُّونَ ٱلنَّٰصِحِينَ","1060":"فَأَلۡقَىٰ عَصَاهُ فَإِذَا هِيَ ثُعۡبَانٞ مُّبِينٞ","1086":"فَأَرۡسَلۡنَا عَلَيۡهِمُ ٱلطُّوفَانَ وَٱلۡجَرَادَ وَٱلۡقُمَّلَ وَٱلضَّفَادِعَ وَٱلدَّمَ ءَايَٰتٖ مُّفَصَّلَٰتٖ فَٱسۡتَكۡبَرُواْ وَكَانُواْ قَوۡمٗا مُّجۡرِمِينَ","1116":"وَسۡـَٔلۡهُمۡ عَنِ ٱلۡقَرۡيَةِ ٱلَّتِي كَانَتۡ حَاضِرَةَ ٱلۡبَحۡرِ إِذۡ يَعۡدُونَ فِي ٱلسَّبۡتِ إِذۡ تَأۡتِيهِمۡ حِيتَانُهُمۡ يَوۡمَ سَبۡتِهِمۡ شُرَّعٗا وَيَوۡمَ لَا يَسۡبِتُونَ لَا تَأۡتِيهِمۡۚ كَذَٰلِكَ نَبۡلُوهُم بِمَا كَانُواْ يَفۡسُقُونَ","1117":"وَإِذۡ قَالَتۡ أُمَّةٞ مِّنۡهُمۡ لِمَ تَعِظُونَ قَوۡمًا ٱللَّهُ مُهۡلِكُهُمۡ أَوۡ مُعَذِّبُهُمۡ عَذَابٗا شَدِيدٗاۖ قَالُواْ مَعۡذِرَةً إِلَىٰ رَبِّكُمۡ وَلَعَلَّهُمۡ يَتَّقُونَ","1118":"فَلَمَّا نَسُواْ مَا ذُكِّرُواْ بِهِۦٓ أَنجَيۡنَا ٱلَّذِينَ يَنۡهَوۡنَ عَنِ ٱلسُّوٓءِ وَأَخَذۡنَا ٱلَّذِينَ ظَلَمُواْ بِعَذَابِۭ بَـِٔيسِۭ بِمَا كَانُواْ يَفۡسُقُونَ","1119":"فَلَمَّا عَتَوۡاْ عَن مَّا نُهُواْ عَنۡهُ قُلۡنَا لَهُمۡ كُونُواْ قِرَدَةً خَٰسِـِٔينَ","1128":"وَٱتۡلُ عَلَيۡهِمۡ نَبَأَ ٱلَّذِيٓ ءَاتَيۡنَٰهُ ءَايَٰتِنَا فَٱنسَلَخَ مِنۡهَا فَأَتۡبَعَهُ ٱلشَّيۡطَٰنُ فَكَانَ مِنَ ٱلۡغَاوِينَ","1129":"وَلَوۡ شِئۡنَا لَرَفَعۡنَٰهُ بِهَا وَلَٰكِنَّهُۥٓ أَخۡلَدَ إِلَى ٱلۡأَرۡضِ وَٱتَّبَعَ هَوَىٰهُۚ فَمَثَلُهُۥ كَمَثَلِ ٱلۡكَلۡبِ إِن تَحۡمِلۡ عَلَيۡهِ يَلۡهَثۡ أَوۡ تَتۡرُكۡهُ يَلۡهَثۚ ذَّٰلِكَ مَثَلُ ٱلۡقَوۡمِ ٱلَّذِينَ كَذَّبُواْ بِـَٔايَٰتِنَاۚ فَٱقۡصُصِ ٱلۡقَصَصَ لَعَلَّهُمۡ يَتَفَكَّرُونَ","1181":"۞ إِنَّ شَرَّ ٱلدَّوَآبِّ عِندَ ٱللَّهِ ٱلصُّمُّ ٱلۡبُكۡمُ ٱلَّذِينَ لَا يَعۡقِلُونَ","1214":"إِنَّ شَرَّ ٱلدَّوَآبِّ عِندَ ٱللَّهِ ٱلَّذِينَ كَفَرُواْ فَهُمۡ لَا يُؤۡمِنُونَ","1478":"۞ وَمَا مِن دَآبَّةٖ فِي ٱلۡأَرۡضِ إِلَّا عَلَى ٱللَّهِ رِزۡقُهَا وَيَعۡلَمُ مُسۡتَقَرَّهَا وَمُسۡتَوۡدَعَهَاۚ كُلّٞ فِي كِتَٰبٖ مُّبِينٖ","1536":"وَيَٰقَوۡمِ هَٰذِهِۦ نَاقَةُ ٱللَّهِ لَكُمۡ ءَايَةٗۖ فَذَرُوهَا تَأۡكُلۡ فِيٓ أَرۡضِ ٱللَّهِۖ وَلَا تَمَسُّوهَا بِسُوٓءٖ فَيَأۡخُذَكُمۡ عَذَابٞ قَرِيبٞ","1537":"فَعَقَرُوهَا فَقَالَ تَمَتَّعُواْ فِي دَارِكُمۡ ثَلَٰثَةَ أَيَّامٖۖ ذَٰلِكَ وَعۡدٌ غَيۡرُ مَكۡذُوبٖ","1608":"قَالَ إِنِّي لَيَحۡزُنُنِيٓ أَن تَذۡهَبُواْ بِهِۦ وَأَخَافُ أَن يَأۡكُلَهُ ٱلذِّئۡبُ وَأَنتُمۡ عَنۡهُ غَٰفِلُونَ","1609":"قَالُواْ لَئِنۡ أَكَلَهُ ٱلذِّئۡبُ وَنَحۡنُ عُصۡبَةٌ إِنَّآ إِذٗا لَّخَٰسِرُونَ","1610":"فَلَمَّا ذَهَبُواْ بِهِۦ وَأَجۡمَعُوٓاْ أَن يَجۡعَلُوهُ فِي غَيَٰبَتِ ٱلۡجُبِّۚ وَأَوۡحَيۡنَآ إِلَيۡهِ لَتُنَبِّئَنَّهُم بِأَمۡرِهِمۡ هَٰذَا وَهُمۡ لَا يَشۡعُرُونَ","1611":"وَجَآءُوٓ أَبَاهُمۡ عِشَآءٗ يَبۡكُونَ","1612":"قَالُواْ يَٰٓأَبَانَآ إِنَّا ذَهَبۡنَا نَسۡتَبِقُ وَتَرَكۡنَا يُوسُفَ عِندَ مَتَٰعِنَا فَأَكَلَهُ ٱلذِّئۡبُۖ وَمَآ أَنتَ بِمُؤۡمِنٖ لَّنَا وَلَوۡ كُنَّا صَٰدِقِينَ","1905":"وَٱلۡأَنۡعَٰمَ خَلَقَهَاۖ لَكُمۡ فِيهَا دِفۡءٞ وَمَنَٰفِعُ وَمِنۡهَا تَأۡكُلُونَ","1906":"وَلَكُمۡ فِيهَا جَمَالٌ حِينَ تُرِيحُونَ وَحِينَ تَسۡرَحُونَ","1907":"وَتَحۡمِلُ أَثۡقَالَكُمۡ إِلَىٰ بَلَدٖ لَّمۡ تَكُونُواْ بَٰلِغِيهِ إِلَّا بِشِقِّ ٱلۡأَنفُسِۚ إِنَّ رَبَّكُمۡ لَرَءُوفٞ رَّحِيمٞ","1908":"وَٱلۡخَيۡلَ وَٱلۡبِغَالَ وَٱلۡحَمِيرَ لِتَرۡكَبُوهَا وَزِينَةٗۚ وَيَخۡلُقُ مَا لَا تَعۡلَمُونَ","1968":"وَأَوۡحَىٰ رَبُّكَ إِلَى ٱلنَّحۡلِ أَنِ ٱتَّخِذِي مِنَ ٱلۡجِبَالِ بُيُوتٗا وَمِنَ ٱلشَّجَرِ وَمِمَّا يَعۡرِشُونَ","1969":"ثُمَّ كُلِي مِن كُلِّ ٱلثَّمَرَٰتِ فَٱسۡلُكِي سُبُلَ رَبِّكِ ذُلُلٗاۚ يَخۡرُجُ مِنۢ بُطُونِهَا شَرَابٞ مُّخۡتَلِفٌ أَلۡوَٰنُهُۥ فِيهِ شِفَآءٞ لِّلنَّاسِۚ إِنَّ فِي ذَٰلِكَ لَأٓيَةٗ لِّقَوۡمٖ يَتَفَكَّرُونَ","1979":"أَلَمۡ يَرَوۡاْ إِلَى ٱلطَّيۡرِ مُسَخَّرَٰتٖ فِي جَوِّ ٱلسَّمَآءِ مَا يُمۡسِكُهُنَّ إِلَّا ٱللَّهُۚ إِنَّ فِي ذَٰلِكَ لَأٓيَٰتٖ لِّقَوۡمٖ يُؤۡمِنُونَ","2072":"تُسَبِّحُ لَهُ ٱلسَّمَٰوَٰتُ ٱلسَّبۡعُ وَٱلۡأَرۡضُ وَمَن فِيهِنَّۚ وَإِن مِّن شَيۡءٍ إِلَّا يُسَبِّحُ بِحَمۡدِهِۦ وَلَٰكِن لَّا تَفۡقَهُونَ تَسۡبِيحَهُمۡۚ إِنَّهُۥ كَانَ حَلِيمًا غَفُورٗا","2157":"وَتَحۡسَبُهُمۡ أَيۡقَاظٗا وَهُمۡ رُقُودٞۚ وَنُقَلِّبُهُمۡ ذَاتَ ٱلۡيَمِينِ وَذَاتَ ٱلشِّمَالِۖ وَكَلۡبُهُم بَٰسِطٞ ذِرَاعَيۡهِ بِٱلۡوَصِيدِۚ لَوِ ٱطَّلَعۡتَ عَلَيۡهِمۡ لَوَلَّيۡتَ مِنۡهُمۡ فِرَارٗا وَلَمُلِئۡتَ مِنۡهُمۡ رُعۡبٗا","2161":"سَيَقُولُونَ ثَلَٰثَةٞ رَّابِعُهُمۡ كَلۡبُهُمۡ وَيَقُولُونَ خَمۡسَةٞ سَادِسُهُمۡ كَلۡبُهُمۡ رَجۡمَۢا بِٱلۡغَيۡبِۖ وَيَقُولُونَ سَبۡعَةٞ وَثَامِنُهُمۡ كَلۡبُهُمۡۚ قُل رَّبِّيٓ أَعۡلَمُ بِعِدَّتِهِم مَّا يَعۡلَمُهُمۡ إِلَّا قَلِيلٞۗ فَلَا تُمَارِ فِيهِمۡ إِلَّا مِرَآءٗ ظَٰهِرٗا وَلَا تَسۡتَفۡتِ فِيهِم مِّنۡهُمۡ أَحَدٗا","2199":"وَإِذۡ قَالَ مُوسَىٰ لِفَتَىٰهُ لَآ أَبۡرَحُ حَتَّىٰٓ أَبۡلُغَ مَجۡمَعَ ٱلۡبَحۡرَيۡنِ أَوۡ أَمۡضِيَ حُقُبٗا","2200":"فَلَمَّا بَلَغَا مَجۡمَعَ بَيۡنِهِمَا نَسِيَا حُوتَهُمَا فَٱتَّخَذَ سَبِيلَهُۥ فِي ٱلۡبَحۡرِ سَرَبٗا","2201":"فَلَمَّا جَاوَزَا قَالَ لِفَتَىٰهُ ءَاتِنَا غَدَآءَنَا لَقَدۡ لَقِينَا مِن سَفَرِنَا هَٰذَا نَصَبٗا","2202":"قَالَ أَرَءَيۡتَ إِذۡ أَوَيۡنَآ إِلَى ٱلصَّخۡرَةِ فَإِنِّي نَسِيتُ ٱلۡحُوتَ وَمَآ أَنسَىٰنِيهُ إِلَّا ٱلشَّيۡطَٰنُ أَنۡ أَذۡكُرَهُۥۚ وَٱتَّخَذَ سَبِيلَهُۥ فِي ٱلۡبَحۡرِ عَجَبٗا","2203":"قَالَ ذَٰلِكَ مَا كُنَّا نَبۡغِۚ فَٱرۡتَدَّا عَلَىٰٓ ءَاثَارِهِمَا قَصَصٗا","2364":"وَمَا تِلۡكَ بِيَمِينِكَ يَٰمُوسَىٰ","2365":"قَالَ هِيَ عَصَايَ أَتَوَكَّؤُاْ عَلَيۡهَا وَأَهُشُّ بِهَا عَلَىٰ غَنَمِي وَلِيَ فِيهَا مَـَٔارِبُ أُخۡرَىٰ","2366":"قَالَ أَلۡقِهَا يَٰمُوسَىٰ","2367":"فَأَلۡقَىٰهَا فَإِذَا هِيَ حَيَّةٞ تَسۡعَىٰ","2368":"قَالَ خُذۡهَا وَلَا تَخَفۡۖ سَنُعِيدُهَا سِيرَتَهَا ٱلۡأُولَىٰ","2569":"وَذَا ٱلنُّونِ إِذ ذَّهَبَ مُغَٰضِبٗا فَظَنَّ أَن لَّن نَّقۡدِرَ عَلَيۡهِ فَنَادَىٰ فِي ٱلظُّلُمَٰتِ أَن لَّآ إِلَٰهَ إِلَّآ أَنتَ سُبۡحَٰنَكَ إِنِّي كُنتُ مِنَ ٱلظَّٰلِمِينَ","2570":"فَٱسۡتَجَبۡنَا لَهُۥ وَنَجَّيۡنَٰهُ مِنَ ٱلۡغَمِّۚ وَكَذَٰلِكَ نُـۨجِي ٱلۡمُؤۡمِنِينَ","2612":"أَلَمۡ تَرَ أَنَّ ٱللَّهَ يَسۡجُدُۤ لَهُۥۤ مَن فِي ٱلسَّمَٰوَٰتِ وَمَن فِي ٱلۡأَرۡضِ وَٱلشَّمۡسُ وَٱلۡقَمَرُ وَٱلنُّجُومُ وَٱلۡجِبَالُ وَٱلشَّجَرُ وَٱلدَّوَآبُّ وَكَثِيرٞ مِّنَ ٱلنَّاسِۖ وَكَثِيرٌ حَقَّ عَلَيۡهِ ٱلۡعَذَابُۗ وَمَن يُهِنِ ٱللَّهُ فَمَا لَهُۥ مِن مُّكۡرِمٍۚ إِنَّ ٱللَّهَ يَفۡعَلُ مَا يَشَآءُ۩","2667":"يَٰٓأَيُّهَا ٱلنَّاسُ ضُرِبَ مَثَلٞ فَٱسۡتَمِعُواْ لَهُۥٓۚ إِنَّ ٱلَّذِينَ تَدۡعُونَ مِن دُونِ ٱللَّهِ لَن يَخۡلُقُواْ ذُبَابٗا وَلَوِ ٱجۡتَمَعُواْ لَهُۥۖ وَإِن يَسۡلُبۡهُمُ ٱلذُّبَابُ شَيۡـٔٗا لَّا يَسۡتَنقِذُوهُ مِنۡهُۚ ضَعُفَ ٱلطَّالِبُ وَٱلۡمَطۡلُوبُ","2668":"مَا قَدَرُواْ ٱللَّهَ حَقَّ قَدۡرِهِۦٓۚ إِنَّ ٱللَّهَ لَقَوِيٌّ عَزِيزٌ","2693":"وَإِنَّ لَكُمۡ فِي ٱلۡأَنۡعَٰمِ لَعِبۡرَةٗۖ نُّسۡقِيكُم مِّمَّا فِي بُطُونِهَا وَلَكُمۡ فِيهَا مَنَٰفِعُ كَثِيرَةٞ وَمِنۡهَا تَأۡكُلُونَ","2694":"وَعَلَيۡهَا وَعَلَى ٱلۡفُلۡكِ تُحۡمَلُونَ","2831":"أَلَمۡ تَرَ أَنَّ ٱللَّهَ يُسَبِّحُ لَهُۥ مَن فِي ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ وَٱلطَّيۡرُ صَٰٓفَّٰتٖۖ كُلّٞ قَدۡ عَلِمَ صَلَاتَهُۥ وَتَسۡبِيحَهُۥۗ وَٱللَّهُ عَلِيمُۢ بِمَا يَفۡعَلُونَ","2835":"وَٱللَّهُ خَلَقَ كُلَّ دَآبَّةٖ مِّن مَّآءٖۖ فَمِنۡهُم مَّن يَمۡشِي عَلَىٰ بَطۡنِهِۦ وَمِنۡهُم مَّن يَمۡشِي عَلَىٰ رِجۡلَيۡنِ وَمِنۡهُم مَّن يَمۡشِي عَلَىٰٓ أَرۡبَعٖۚ يَخۡلُقُ ٱللَّهُ مَا يَشَآءُۚ إِنَّ ٱللَّهَ عَلَىٰ كُلِّ شَيۡءٖ قَدِيرٞ","2963":"فَأَلۡقَىٰ عَصَاهُ فَإِذَا هِيَ ثُعۡبَانٞ مُّبِينٞ","3174":"وَوَرِثَ سُلَيۡمَٰنُ دَاوُۥدَۖ وَقَالَ يَٰٓأَيُّهَا ٱلنَّاسُ عُلِّمۡنَا مَنطِقَ ٱلطَّيۡرِ وَأُوتِينَا مِن كُلِّ شَيۡءٍۖ إِنَّ هَٰذَا لَهُوَ ٱلۡفَضۡلُ ٱلۡمُبِينُ","3175":"وَحُشِرَ لِسُلَيۡمَٰنَ جُنُودُهُۥ مِنَ ٱلۡجِنِّ وَٱلۡإِنسِ وَٱلطَّيۡرِ فَهُمۡ يُوزَعُونَ","3176":"حَتَّىٰٓ إِذَآ أَتَوۡاْ عَلَىٰ وَادِ ٱلنَّمۡلِ قَالَتۡ نَمۡلَةٞ يَٰٓأَيُّهَا ٱلنَّمۡلُ ٱدۡخُلُواْ مَسَٰكِنَكُمۡ لَا يَحۡطِمَنَّكُمۡ سُلَيۡمَٰنُ وَجُنُودُهُۥ وَهُمۡ لَا يَشۡعُرُونَ","3177":"فَتَبَسَّمَ ضَاحِكٗا مِّن قَوۡلِهَا وَقَالَ رَبِّ أَوۡزِعۡنِيٓ أَنۡ أَشۡكُرَ نِعۡمَتَكَ ٱلَّتِيٓ أَنۡعَمۡتَ عَلَيَّ وَعَلَىٰ وَٰلِدَيَّ وَأَنۡ أَعۡمَلَ صَٰلِحٗا تَرۡضَىٰهُ وَأَدۡخِلۡنِي بِرَحۡمَتِكَ فِي عِبَادِكَ ٱلصَّٰلِحِينَ","3178":"وَتَفَقَّدَ ٱلطَّيۡرَ فَقَالَ مَالِيَ لَآ أَرَى ٱلۡهُدۡهُدَ أَمۡ كَانَ مِنَ ٱلۡغَآئِبِينَ","3179":"لَأُعَذِّبَنَّهُۥ عَذَابٗا شَدِيدًا أَوۡ لَأَاْذۡبَحَنَّهُۥٓ أَوۡ لَيَأۡتِيَنِّي بِسُلۡطَٰنٖ مُّبِينٖ","3180":"فَمَكَثَ غَيۡرَ بَعِيدٖ فَقَالَ أَحَطتُ بِمَا لَمۡ تُحِطۡ بِهِۦ وَجِئۡتُكَ مِن سَبَإِۭ بِنَبَإٖ يَقِينٍ","3181":"إِنِّي وَجَدتُّ ٱمۡرَأَةٗ تَمۡلِكُهُمۡ وَأُوتِيَتۡ مِن كُلِّ شَيۡءٖ وَلَهَا عَرۡشٌ عَظِيمٞ","3182":"وَجَدتُّهَا وَقَوۡمَهَا يَسۡجُدُونَ لِلشَّمۡسِ مِن دُونِ ٱللَّهِ وَزَيَّنَ لَهُمُ ٱلشَّيۡطَٰنُ أَعۡمَٰلَهُمۡ فَصَدَّهُمۡ عَنِ ٱلسَّبِيلِ فَهُمۡ لَا يَهۡتَدُونَ","3183":"أَلَّاۤ يَسۡجُدُواْۤ لِلَّهِ ٱلَّذِي يُخۡرِجُ ٱلۡخَبۡءَ فِي ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ وَيَعۡلَمُ مَا تُخۡفُونَ وَمَا تُعۡلِنُونَ","3184":"ٱللَّهُ لَآ إِلَٰهَ إِلَّا هُوَ رَبُّ ٱلۡعَرۡشِ ٱلۡعَظِيمِ۩","3185":"۞ قَالَ سَنَنظُرُ أَصَدَقۡتَ أَمۡ كُنتَ مِنَ ٱلۡكَٰذِبِينَ","3186":"ٱذۡهَب بِّكِتَٰبِي هَٰذَا فَأَلۡقِهۡ إِلَيۡهِمۡ ثُمَّ تَوَلَّ عَنۡهُمۡ فَٱنظُرۡ مَاذَا يَرۡجِعُونَ","3240":"۞ وَإِذَا وَقَعَ ٱلۡقَوۡلُ عَلَيۡهِمۡ أَخۡرَجۡنَا لَهُمۡ دَآبَّةٗ مِّنَ ٱلۡأَرۡضِ تُكَلِّمُهُمۡ أَنَّ ٱلنَّاسَ كَانُواْ بِـَٔايَٰتِنَا لَا يُوقِنُونَ","3380":"مَثَلُ ٱلَّذِينَ ٱتَّخَذُواْ مِن دُونِ ٱللَّهِ أَوۡلِيَآءَ كَمَثَلِ ٱلۡعَنكَبُوتِ ٱتَّخَذَتۡ بَيۡتٗاۖ وَإِنَّ أَوۡهَنَ ٱلۡبُيُوتِ لَبَيۡتُ ٱلۡعَنكَبُوتِۚ لَوۡ كَانُواْ يَعۡلَمُونَ","3399":"وَكَأَيِّن مِّن دَآبَّةٖ لَّا تَحۡمِلُ رِزۡقَهَا ٱللَّهُ يَرۡزُقُهَا وَإِيَّاكُمۡۚ وَهُوَ ٱلسَّمِيعُ ٱلۡعَلِيمُ","3615":"۞ وَلَقَدۡ ءَاتَيۡنَا دَاوُۥدَ مِنَّا فَضۡلٗاۖ يَٰجِبَالُ أَوِّبِي مَعَهُۥ وَٱلطَّيۡرَۖ وَأَلَنَّا لَهُ ٱلۡحَدِيدَ","3775":"أَوَلَمۡ يَرَوۡاْ أَنَّا خَلَقۡنَا لَهُم مِّمَّا عَمِلَتۡ أَيۡدِينَآ أَنۡعَٰمٗا فَهُمۡ لَهَا مَٰلِكُونَ","3776":"وَذَلَّلۡنَٰهَا لَهُمۡ فَمِنۡهَا رَكُوبُهُمۡ وَمِنۡهَا يَأۡكُلُونَ","3777":"وَلَهُمۡ فِيهَا مَنَٰفِعُ وَمَشَارِبُۚ أَفَلَا يَشۡكُرُونَ","3887":"رَبِّ هَبۡ لِي مِنَ ٱلصَّٰلِحِينَ","3888":"فَبَشَّرۡنَٰهُ بِغُلَٰمٍ حَلِيمٖ","3889":"فَلَمَّا بَلَغَ مَعَهُ ٱلسَّعۡيَ قَالَ يَٰبُنَيَّ إِنِّيٓ أَرَىٰ فِي ٱلۡمَنَامِ أَنِّيٓ أَذۡبَحُكَ فَٱنظُرۡ مَاذَا تَرَىٰۚ قَالَ يَٰٓأَبَتِ ٱفۡعَلۡ مَا تُؤۡمَرُۖ سَتَجِدُنِيٓ إِن شَآءَ ٱللَّهُ مِنَ ٱلصَّٰبِرِينَ","3890":"فَلَمَّآ أَسۡلَمَا وَتَلَّهُۥ لِلۡجَبِينِ","3891":"وَنَٰدَيۡنَٰهُ أَن يَٰٓإِبۡرَٰهِيمُ","3892":"قَدۡ صَدَّقۡتَ ٱلرُّءۡيَآۚ إِنَّا كَذَٰلِكَ نَجۡزِي ٱلۡمُحۡسِنِينَ","3893":"إِنَّ هَٰذَا لَهُوَ ٱلۡبَلَٰٓؤُاْ ٱلۡمُبِينُ","3894":"وَفَدَيۡنَٰهُ بِذِبۡحٍ عَظِيمٖ","3895":"وَتَرَكۡنَا عَلَيۡهِ فِي ٱلۡأٓخِرِينَ","3896":"سَلَٰمٌ عَلَىٰٓ إِبۡرَٰهِيمَ","3897":"كَذَٰلِكَ نَجۡزِي ٱلۡمُحۡسِنِينَ","3898":"إِنَّهُۥ مِنۡ عِبَادِنَا ٱلۡمُؤۡمِنِينَ","3926":"وَإِنَّ يُونُسَ لَمِنَ ٱلۡمُرۡسَلِينَ","3927":"إِذۡ أَبَقَ إِلَى ٱلۡفُلۡكِ ٱلۡمَشۡحُونِ","3928":"فَسَاهَمَ فَكَانَ مِنَ ٱلۡمُدۡحَضِينَ","3929":"فَٱلۡتَقَمَهُ ٱلۡحُوتُ وَهُوَ مُلِيمٞ","3930":"فَلَوۡلَآ أَنَّهُۥ كَانَ مِنَ ٱلۡمُسَبِّحِينَ","3931":"لَلَبِثَ فِي بَطۡنِهِۦٓ إِلَىٰ يَوۡمِ يُبۡعَثُونَ","3932":"۞ فَنَبَذۡنَٰهُ بِٱلۡعَرَآءِ وَهُوَ سَقِيمٞ","3933":"وَأَنۢبَتۡنَا عَلَيۡهِ شَجَرَةٗ مِّن يَقۡطِينٖ","3934":"وَأَرۡسَلۡنَٰهُ إِلَىٰ مِاْئَةِ أَلۡفٍ أَوۡ يَزِيدُونَ","3935":"فَـَٔامَنُواْ فَمَتَّعۡنَٰهُمۡ إِلَىٰ حِينٖ","3986":"ٱصۡبِرۡ عَلَىٰ مَا يَقُولُونَ وَٱذۡكُرۡ عَبۡدَنَا دَاوُۥدَ ذَا ٱلۡأَيۡدِۖ إِنَّهُۥٓ أَوَّابٌ","3987":"إِنَّا سَخَّرۡنَا ٱلۡجِبَالَ مَعَهُۥ يُسَبِّحۡنَ بِٱلۡعَشِيِّ وَٱلۡإِشۡرَاقِ","3988":"وَٱلطَّيۡرَ مَحۡشُورَةٗۖ كُلّٞ لَّهُۥٓ أَوَّابٞ","3999":"وَوَهَبۡنَا لِدَاوُۥدَ سُلَيۡمَٰنَۚ نِعۡمَ ٱلۡعَبۡدُ إِنَّهُۥٓ أَوَّابٌ","4000":"إِذۡ عُرِضَ عَلَيۡهِ بِٱلۡعَشِيِّ ٱلصَّٰفِنَٰتُ ٱلۡجِيَادُ","4001":"فَقَالَ إِنِّيٓ أَحۡبَبۡتُ حُبَّ ٱلۡخَيۡرِ عَن ذِكۡرِ رَبِّي حَتَّىٰ تَوَارَتۡ بِٱلۡحِجَابِ","4002":"رُدُّوهَا عَلَيَّۖ فَطَفِقَ مَسۡحَۢا بِٱلسُّوقِ وَٱلۡأَعۡنَاقِ","4211":"ٱللَّهُ ٱلَّذِي جَعَلَ لَكُمُ ٱلۡأَنۡعَٰمَ لِتَرۡكَبُواْ مِنۡهَا وَمِنۡهَا تَأۡكُلُونَ","4212":"وَلَكُمۡ فِيهَا مَنَٰفِعُ وَلِتَبۡلُغُواْ عَلَيۡهَا حَاجَةٗ فِي صُدُورِكُمۡ وَعَلَيۡهَا وَعَلَى ٱلۡفُلۡكِ تُحۡمَلُونَ","4851":"فَتَوَلَّ عَنۡهُمۡۘ يَوۡمَ يَدۡعُ ٱلدَّاعِ إِلَىٰ شَيۡءٖ نُّكُرٍ","4852":"خُشَّعًا أَبۡصَٰرُهُمۡ يَخۡرُجُونَ مِنَ ٱلۡأَجۡدَاثِ كَأَنَّهُمۡ جَرَادٞ مُّنتَشِرٞ","4853":"مُّهۡطِعِينَ إِلَى ٱلدَّاعِۖ يَقُولُ ٱلۡكَٰفِرُونَ هَٰذَا يَوۡمٌ عَسِرٞ","4872":"إِنَّا مُرۡسِلُواْ ٱلنَّاقَةِ فِتۡنَةٗ لَّهُمۡ فَٱرۡتَقِبۡهُمۡ وَٱصۡطَبِرۡ","4873":"وَنَبِّئۡهُمۡ أَنَّ ٱلۡمَآءَ قِسۡمَةُۢ بَيۡنَهُمۡۖ كُلُّ شِرۡبٖ مُّحۡتَضَرٞ","4874":"فَنَادَوۡاْ صَاحِبَهُمۡ فَتَعَاطَىٰ فَعَقَرَ","4875":"فَكَيۡفَ كَانَ عَذَابِي وَنُذُرِ","4876":"إِنَّآ أَرۡسَلۡنَا عَلَيۡهِمۡ صَيۡحَةٗ وَٰحِدَةٗ فَكَانُواْ كَهَشِيمِ ٱلۡمُحۡتَظِرِ","5181":"مَثَلُ ٱلَّذِينَ حُمِّلُواْ ٱلتَّوۡرَىٰةَ ثُمَّ لَمۡ يَحۡمِلُوهَا كَمَثَلِ ٱلۡحِمَارِ يَحۡمِلُ أَسۡفَارَۢاۚ بِئۡسَ مَثَلُ ٱلۡقَوۡمِ ٱلَّذِينَ كَذَّبُواْ بِـَٔايَٰتِ ٱللَّهِۚ وَٱللَّهُ لَا يَهۡدِي ٱلۡقَوۡمَ ٱلظَّٰلِمِينَ","5259":"أَوَلَمۡ يَرَوۡاْ إِلَى ٱلطَّيۡرِ فَوۡقَهُمۡ صَٰٓفَّٰتٖ وَيَقۡبِضۡنَۚ مَا يُمۡسِكُهُنَّ إِلَّا ٱلرَّحۡمَٰنُۚ إِنَّهُۥ بِكُلِّ شَيۡءِۭ بَصِيرٌ","5318":"فَٱصۡبِرۡ لِحُكۡمِ رَبِّكَ وَلَا تَكُن كَصَاحِبِ ٱلۡحُوتِ إِذۡ نَادَىٰ وَهُوَ مَكۡظُومٞ","5319":"لَّوۡلَآ أَن تَدَٰرَكَهُۥ نِعۡمَةٞ مِّن رَّبِّهِۦ لَنُبِذَ بِٱلۡعَرَآءِ وَهُوَ مَذۡمُومٞ","5320":"فَٱجۡتَبَٰهُ رَبُّهُۥ فَجَعَلَهُۥ مِنَ ٱلصَّٰلِحِينَ","5983":"أَفَلَا يَنظُرُونَ إِلَى ٱلۡإِبِلِ كَيۡفَ خُلِقَتۡ","5984":"وَإِلَى ٱلسَّمَآءِ كَيۡفَ رُفِعَتۡ","5985":"وَإِلَى ٱلۡجِبَالِ كَيۡفَ نُصِبَتۡ","5986":"وَإِلَى ٱلۡأَرۡضِ كَيۡفَ سُطِحَتۡ","6053":"كَذَّبَتۡ ثَمُودُ بِطَغۡوَىٰهَآ","6054":"إِذِ ٱنۢبَعَثَ أَشۡقَىٰهَا","6055":"فَقَالَ لَهُمۡ رَسُولُ ٱللَّهِ نَاقَةَ ٱللَّهِ وَسُقۡيَٰهَا","6056":"فَكَذَّبُوهُ فَعَقَرُوهَا فَدَمۡدَمَ عَلَيۡهِمۡ رَبُّهُم بِذَنۢبِهِمۡ فَسَوَّىٰهَا","6057":"وَلَا يَخَافُ عُقۡبَٰهَا","6146":"وَٱلۡعَٰدِيَٰتِ ضَبۡحٗا","6147":"فَٱلۡمُورِيَٰتِ قَدۡحٗا","6148":"فَٱلۡمُغِيرَٰتِ صُبۡحٗا","6149":"فَأَثَرۡنَ بِهِۦ نَقۡعٗا","6150":"فَوَسَطۡنَ بِهِۦ جَمۡعًا","6151":"إِنَّ ٱلۡإِنسَٰنَ لِرَبِّهِۦ لَكَنُودٞ","6160":"يَوۡمَ يَكُونُ ٱلنَّاسُ كَٱلۡفَرَاشِ ٱلۡمَبۡثُوثِ","6188":"أَلَمۡ تَرَ كَيۡفَ فَعَلَ رَبُّكَ بِأَصۡحَٰبِ ٱلۡفِيلِ","6189":"أَلَمۡ يَجۡعَلۡ كَيۡدَهُمۡ فِي تَضۡلِيلٖ","6190":"وَأَرۡسَلَ عَلَيۡهِمۡ طَيۡرًا أَبَابِيلَ","6191":"تَرۡمِيهِم بِحِجَارَةٖ مِّن سِجِّيلٖ","6192":"فَجَعَلَهُمۡ كَعَصۡفٖ مَّأۡكُولِۭ"},"nay":164,"nq":83};
